import socket
import time
import signal
import sys
import threading

try:
    from gpiozero import DigitalOutputDevice, PWMOutputDevice
except Exception:
    DigitalOutputDevice = None
    PWMOutputDevice = None

try:
    from gpiozero.pins.native import NativeFactory
except Exception:
    NativeFactory = None

try:
    from gpiozero.pins.lgpio import LGPIOFactory
except Exception:
    LGPIOFactory = None

try:
    from gpiozero.pins.rpigpio import RPiGPIOFactory
except Exception:
    RPiGPIOFactory = None

try:
    from gpiozero.pins.pigpio import PiGPIOFactory
except Exception:
    PiGPIOFactory = None

try:
    from gpiozero.pins.mock import MockFactory
except Exception:
    MockFactory = None

try:
    from mcp3008 import MCP3008
except Exception:
    MCP3008 = None

# Constants
MOTOR_A_FORWARD_PIN = 27
MOTOR_A_BACKWARD_PIN = 22
MOTOR_B_CLOCKWISE_PIN = 24
MOTOR_B_COUNTERCLOCKWISE_PIN = 25
MOTOR_A_ENABLE_PIN = 17
MOTOR_B_ENABLE_PIN = 23
SPI_CLK_PIN = 11
SPI_MOSI_PIN = 10
SPI_MISO_PIN = 9
SPI_CS_1_PIN = 8
SPI_CS_2_PIN = 7
WATER_PUMP_PIN = 18

DEFAULT_THRESHOLD = 300
DEFAULT_WATERING_DURATION = 5

# Global state
threshold = DEFAULT_THRESHOLD
watering_duration = DEFAULT_WATERING_DURATION
last_watering_time = 0
sensor_data = {"sensor1": 0, "sensor2": 0}

# Hardware objects
motor_a_forward = None
motor_a_backward = None
motor_b_clockwise = None
motor_b_counterclockwise = None
motor_a_enable = None
motor_b_enable = None
water_pump = None
mcp1 = None
mcp2 = None

# Socket
server_socket = None

# Lock for thread-safe access to sensor_data
sensor_data_lock = threading.Lock()

# GPIO factory selection
factory = None
if NativeFactory is not None:
    factory = NativeFactory()
elif LGPIOFactory is not None:
    factory = LGPIOFactory()
elif RPiGPIOFactory is not None:
    factory = RPiGPIOFactory()
elif PiGPIOFactory is not None:
    factory = PiGPIOFactory()
elif MockFactory is not None:
    factory = MockFactory()

def initialize_gpio():
    global motor_a_forward, motor_a_backward, motor_b_clockwise, motor_b_counterclockwise
    global motor_a_enable, motor_b_enable, water_pump, mcp1, mcp2

    if DigitalOutputDevice is None or PWMOutputDevice is None:
        print("Error: gpiozero library not available. Running in simulation mode.")
        return False

    try:
        motor_a_forward = DigitalOutputDevice(MOTOR_A_FORWARD_PIN, pin_factory=factory)
        motor_a_backward = DigitalOutputDevice(MOTOR_A_BACKWARD_PIN, pin_factory=factory)
        motor_b_clockwise = DigitalOutputDevice(MOTOR_B_CLOCKWISE_PIN, pin_factory=factory)
        motor_b_counterclockwise = DigitalOutputDevice(MOTOR_B_COUNTERCLOCKWISE_PIN, pin_factory=factory)
        motor_a_enable = PWMOutputDevice(MOTOR_A_ENABLE_PIN, frequency=1000, pin_factory=factory)
        motor_b_enable = PWMOutputDevice(MOTOR_B_ENABLE_PIN, frequency=1000, pin_factory=factory)
        water_pump = DigitalOutputDevice(WATER_PUMP_PIN, pin_factory=factory)

        motor_a_enable.value = 0
        motor_b_enable.value = 0
        water_pump.value = 0

        if MCP3008 is not None:
            mcp1 = MCP3008(channel=0, clock_pin=SPI_CLK_PIN, mosi_pin=SPI_MOSI_PIN, miso_pin=SPI_MISO_PIN, cs_pin=SPI_CS_1_PIN, pin_factory=factory)
            mcp2 = MCP3008(channel=1, clock_pin=SPI_CLK_PIN, mosi_pin=SPI_MOSI_PIN, miso_pin=SPI_MISO_PIN, cs_pin=SPI_CS_2_PIN, pin_factory=factory)
        else:
            print("Warning: mcp3008 library not available. Running in simulation mode.")

        return True
    except Exception as e:
        print(f"Error initializing GPIO: {e}")
        return False

def read_moisture_sensor(mcp, sensor_id):
    if mcp is None:
        return -1
    try:
        total = 0
        for _ in range(5):
            total += mcp.read_adc()
            time.sleep(0.02)
        return total / 5
    except Exception as e:
        print(f"Error reading moisture sensor {sensor_id}: {e}")
        return -1

def get_sensor_data():
    global sensor_data
    with sensor_data_lock:
        return sensor_data.copy()

def set_threshold(new_threshold):
    global threshold
    threshold = new_threshold

def set_watering_duration(new_duration):
    global watering_duration
    watering_duration = new_duration

def water_plant(plant_number):
    global last_watering_time
    with sensor_data_lock:
        if plant_number == 1:
            moisture = sensor_data["sensor1"]
        elif plant_number == 2:
            moisture = sensor_data["sensor2"]
        else:
            print("Invalid plant number.")
            return

    if moisture < 0:
        print("Sensor error, skipping watering.")
        return

    if moisture < threshold:
        print(f"Watering plant {plant_number}...")
        try:
            water_pump.on()
            time.sleep(watering_duration)
            water_pump.off()
            last_watering_time = time.time()
            print(f"Watering complete for plant {plant_number}.")
        except Exception as e:
            print(f"Error watering plant {plant_number}: {e}")
    else:
        print(f"Plant {plant_number} is sufficiently watered.")

def handle_client(client_socket):
    try:
        while True:
            data = client_socket.recv(1024)
            if not data:
                break
            command = data.decode().strip()
            print(f"Received command: {command}")

            if command == "WATER_PLANT_1":
                water_plant(1)
            elif command == "WATER_PLANT_2":
                water_plant(2)
            elif command == "GET_SENSOR_DATA":
                response = str(get_sensor_data())
                client_socket.sendall(response.encode())
            elif command.startswith("SET_THRESHOLD"):
                try:
                    new_threshold = int(command.split()[1])
                    set_threshold(new_threshold)
                    print(f"Threshold set to {new_threshold}")
                except (ValueError, IndexError):
                    print("Invalid threshold value.")
            elif command.startswith("SET_WATERING_DURATION"):
                try:
                    new_duration = int(command.split()[1])
                    set_watering_duration(new_duration)
                    print(f"Watering duration set to {new_duration} seconds")
                except (ValueError, IndexError):
                    print("Invalid watering duration.")
            else:
                print("Invalid command.")

            time.sleep(0.1)
    except Exception as e:
        print(f"Error handling client: {e}")
    finally:
        client_socket.close()

def start_server():
    global server_socket
    try:
        server_socket = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
        server_socket.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)
        server_socket.bind(('0.0.0.0', 12345))
        server_socket.listen(5)
        print("Server listening on port 12345...")
        while True:
            client_socket, address = server_socket.accept()
            print(f"Accepted connection from {address}")
            client_thread = threading.Thread(target=handle_client, args=(client_socket,))
            client_thread.daemon = True
            client_thread.start()
    except Exception as e:
        print(f"Error starting server: {e}")
    finally:
        if server_socket:
            server_socket.close()

def health_check():
    global last_watering_time
    while True:
        time.sleep(60)
        with sensor_data_lock:
            sensor1 = sensor_data["sensor1"]
            sensor2 = sensor_data["sensor2"]

        if sensor1 < 0 or sensor2 < 0:
            print("Sensor error detected. Recalibrating...")
            time.sleep(10)
            continue

        if sensor1 < threshold and time.time() - last_watering_time > 60 * 60:
            print("Plant 1 needs watering.")
        if sensor2 < threshold and time.time() - last_watering_time > 60 * 60:
            print("Plant 2 needs watering.")

def cleanup(signum=None, frame=None):
    print("Cleaning up...")
    if server_socket:
        server_socket.close()
    if motor_a_forward:
        motor_a_forward.close()
    if motor_a_backward:
        motor_a_backward.close()
    if motor_b_clockwise:
        motor_b_clockwise.close()
    if motor_b_counterclockwise:
        motor_b_counterclockwise.close()
    if motor_a_enable:
        motor_a_enable.close()
    if motor_b_enable:
        motor_b_enable.close()
    if water_pump:
        water_pump.close()
    if mcp1:
        mcp1.close()
    if mcp2:
        mcp2.close()
    sys.exit(0)

if __name__ == "__main__":
    signal.signal(signal.SIGINT, cleanup)
    signal.signal(signal.SIGTERM, cleanup)

    if initialize_gpio():
        sensor_thread = threading.Thread(target=health_check)
        sensor_thread.daemon = True
        sensor_thread.start()

        server_thread = threading.Thread(target=start_server)
        server_thread.daemon = True
        server_thread.start()

        while True:
            with sensor_data_lock:
                sensor_data["sensor1"] = read_moisture_sensor(mcp1, 1)
                sensor_data["sensor2"] = read_moisture_sensor(mcp2, 2)
            time.sleep(1)
    else:
        print("GPIO initialization failed. Running in simulation mode.")
        while True:
            time.sleep(1)

