#!/usr/bin/env python3
"""
Greenhouse Controller for Raspberry Pi

Reads temperature/humidity from DHT22 on GPIO 4, controls pump/fan/light
on GPIO 17/27/22, and reads soil moisture from MCP3008 ADC on channel 0.
Logs to greenhouse.log and restarts on watchdog timeout.
"""

import os
import sys
import time
import signal
import logging
import spidev
import board
import adafruit_dht
from gpiozero import OutputDevice, LED

# Configuration
DHT_PIN = board.D4
PUMP_PIN = 17
FAN_PIN = 27
LIGHT_PIN = 22
LED_PIN = 25
SOIL_MOISTURE_CHANNEL = 0
WATCHDOG_TIMEOUT = 600
SENSOR_READ_INTERVAL = 300

# Logging setup
logging.basicConfig(
    filename='greenhouse.log',
    level=logging.INFO,
    format='%(asctime)s - %(levelname)s - %(message)s'
)

# Global state
last_sensor_read_time = 0
last_actuator_command_time = 0
running = True

# Initialize hardware
dht_device = None
pump = None
fan = None
light = None
led = None
spi = None

def signal_handler(signum, frame):
    """Handle SIGTERM and SIGINT for graceful shutdown."""
    global running
    logging.info(f"Received signal {signum}, shutting down...")
    running = False

def setup_hardware():
    """Initialize all hardware components with error handling."""
    global dht_device, pump, fan, light, led, spi

    # Initialize DHT22
    try:
        dht_device = adafruit_dht.DHT22(DHT_PIN, use_pulseio=False)
        logging.info("DHT22 initialized on GPIO 4")
    except Exception as e:
        logging.error(f"Failed to initialize DHT22: {e}")
        dht_device = None

    # Initialize relays
    try:
        pump = OutputDevice(PUMP_PIN, initial_value=False)
        fan = OutputDevice(FAN_PIN, initial_value=False)
        light = OutputDevice(LIGHT_PIN, initial_value=False)
        logging.info("Relays initialized on GPIO 17, 27, 22")
    except Exception as e:
        logging.error(f"Failed to initialize relays: {e}")
        pump = None
        fan = None
        light = None

    # Initialize LED
    try:
        led = LED(LED_PIN)
        led.off()
        logging.info("LED initialized on GPIO 25")
    except Exception as e:
        logging.error(f"Failed to initialize LED: {e}")
        led = None

    # Initialize SPI for MCP3008
    try:
        spi = spidev.SpiDev()
        spi.open(0, 0)  # bus 0, device 0 (CE0)
        spi.max_speed_hz = 1000000
        spi.mode = 0b00
        logging.info("SPI initialized for MCP3008 on bus 0, device 0")
    except Exception as e:
        logging.error(f"Failed to initialize SPI: {e}")
        spi = None

def read_dht22():
    """Read temperature and humidity from DHT22 with retry logic."""
    if dht_device is None:
        logging.warning("DHT22 not initialized, skipping read")
        return None, None

    for attempt in range(3):
        try:
            temperature = dht_device.temperature
            humidity = dht_device.humidity
            if temperature is not None and humidity is not None:
                logging.info(f"DHT22: Temperature={temperature:.1f}°C, Humidity={humidity:.1f}%")
                return temperature, humidity
            else:
                logging.warning(f"DHT22 returned None on attempt {attempt+1}")
        except RuntimeError as e:
            logging.warning(f"DHT22 read error on attempt {attempt+1}: {e}")
        except Exception as e:
            logging.error(f"Unexpected DHT22 error on attempt {attempt+1}: {e}")

        time.sleep(2)

    logging.error("DHT22 read failed after 3 attempts")
    return None, None

def read_mcp3008(channel):
    """Read analog value from MCP3008 ADC via SPI."""
    if spi is None:
        logging.warning("SPI not initialized, skipping MCP3008 read")
        return None

    if not 0 <= channel <= 7:
        logging.error(f"Invalid MCP3008 channel: {channel}")
        return None

    for attempt in range(3):
        try:
            # MCP3008 command: start bit (1), single-ended mode (1), channel (3 bits)
            # Send 3 bytes: [0x01, (0x08 | channel) << 4, 0x00]
            adc = spi.xfer2([0x01, (0x08 | channel) << 4, 0x00])
            data = ((adc[1] & 0x03) << 8) + adc[2]
            logging.debug(f"MCP3008 channel {channel}: raw={data}")
            return data
        except Exception as e:
            logging.error(f"MCP3008 read error on attempt {attempt+1}: {e}")

        time.sleep(0.1)

    logging.error(f"MCP3008 read failed after 3 attempts on channel {channel}")
    return None

def control_pump(command):
    """Control pump relay."""
    if pump is None:
        logging.warning("Pump relay not initialized, cannot control")
        return

    try:
        if command == 'on':
            pump.on()
            logging.info("Pump turned ON")
        elif command == 'off':
            pump.off()
            logging.info("Pump turned OFF")
        else:
            logging.warning(f"Invalid pump command: {command}")
    except Exception as e:
        logging.error(f"Error controlling pump: {e}")

def control_fan(command):
    """Control fan relay."""
    if fan is None:
        logging.warning("Fan relay not initialized, cannot control")
        return

    try:
        if command == 'on':
            fan.on()
            logging.info("Fan turned ON")
        elif command == 'off':
            fan.off()
            logging.info("Fan turned OFF")
        else:
            logging.warning(f"Invalid fan command: {command}")
    except Exception as e:
        logging.error(f"Error controlling fan: {e}")

def control_light(command):
    """Control light relay."""
    if light is None:
        logging.warning("Light relay not initialized, cannot control")
        return

    try:
        if command == 'on':
            light.on()
            logging.info("Light turned ON")
        elif command == 'off':
            light.off()
            logging.info("Light turned OFF")
        else:
            logging.warning(f"Invalid light command: {command}")
    except Exception as e:
        logging.error(f"Error controlling light: {e}")

def set_led_status(status):
    """Set LED status: online (solid on), offline (solid off), error (blink 5x), sync (blink 5x)."""
    if led is None:
        logging.warning("LED not initialized, cannot set status")
        return

    try:
        if status == 'online':
            led.on()
            logging.info("LED set to ONLINE")
        elif status == 'offline':
            led.off()
            logging.info("LED set to OFFLINE")
        elif status == 'error':
            for _ in range(5):
                led.on()
                time.sleep(0.2)
                led.off()
                time.sleep(0.2)
            logging.warning("LED set to ERROR (blinking)")
        elif status == 'synchronizing':
            for _ in range(5):
                led.on()
                time.sleep(0.2)
                led.off()
                time.sleep(0.2)
            logging.info("LED set to SYNCHRONIZING (blinking)")
        else:
            logging.warning(f"Invalid LED status: {status}")
    except Exception as e:
        logging.error(f"Error setting LED status: {e}")

def cleanup():
    """Clean up all hardware resources."""
    logging.info("Cleaning up resources...")

    if dht_device:
        try:
            dht_device.exit()
            logging.info("DHT22 cleaned up")
        except Exception as e:
            logging.error(f"Error cleaning up DHT22: {e}")

    if pump:
        try:
            pump.close()
            logging.info("Pump relay closed")
        except Exception as e:
            logging.error(f"Error closing pump relay: {e}")

    if fan:
        try:
            fan.close()
            logging.info("Fan relay closed")
        except Exception as e:
            logging.error(f"Error closing fan relay: {e}")

    if light:
        try:
            light.close()
            logging.info("Light relay closed")
        except Exception as e:
            logging.error(f"Error closing light relay: {e}")

    if led:
        try:
            led.close()
            logging.info("LED closed")
        except Exception as e:
            logging.error(f"Error closing LED: {e}")

    if spi:
        try:
            spi.close()
            logging.info("SPI closed")
        except Exception as e:
            logging.error(f"Error closing SPI: {e}")

    logging.info("Cleanup complete")

def restart_program():
    """Restart the program using os.execv."""
    logging.info("Restarting program...")
    os.execv(sys.executable, [sys.executable] + sys.argv)

def main():
    """Main program loop."""
    global last_sensor_read_time, last_actuator_command_time, running

    # Register signal handlers
    signal.signal(signal.SIGTERM, signal_handler)
    signal.signal(signal.SIGINT, signal_handler)

    # Setup hardware
    setup_hardware()

    # Set initial LED status
    set_led_status('online')

    logging.info("Greenhouse controller started")

    try:
        while running:
            # Check watchdog timeout
            if time.time() - max(last_sensor_read_time, last_actuator_command_time) > WATCHDOG_TIMEOUT:
                logging.critical("Watchdog timeout! Restarting program...")
                restart_program()

            # Read sensor data
            temperature, humidity = read_dht22()
            if temperature is not None and humidity is not None:
                last_sensor_read_time = time.time()
                logging.info(f"Sensor data: Temperature={temperature:.1f}°C, Humidity={humidity:.1f}%")
            else:
                logging.warning("No valid sensor data received")

            # Read soil moisture
            soil_moisture = read_mcp3008(SOIL_MOISTURE_CHANNEL)
            if soil_moisture is not None:
                logging.info(f"Soil moisture: {soil_moisture}")
            else:
                logging.warning("No valid soil moisture data")

            # Placeholder for actuator control logic (e.g., simple hysteresis)
            # Example: Turn on pump if temperature > 30°C and soil moisture < 300
            if temperature is not None and soil_moisture is not None:
                if temperature > 30 and soil_moisture < 300:
                    control_pump('on')
                else:
                    control_pump('off')

            # Wait for next cycle
            time.sleep(SENSOR_READ_INTERVAL)

    except Exception as e:
        logging.error(f"Unexpected error in main loop: {e}")
    finally:
        cleanup()
        logging.info("Program terminated")

if __name__ == "__main__":
    main()

