import time
import logging
import threading
import queue
import argparse
import spidev
import RPi.GPIO as GPIO

class SoundSensor:
    def __init__(self, sensor_id, sensor_type, threshold, sample_rate, gpio_pins, channels, spi_speed, log_queue):
        self.sensor_id = sensor_id
        self.sensor_type = sensor_type
        self.threshold = threshold
        self.sample_rate = sample_rate
        self.gpio_pins = gpio_pins
        self.channels = channels
        self.spi_speed = spi_speed
        self.log_queue = log_queue
        self.running = False
        self.spi = None
        self.debounce_time = 0.1

        if self.sensor_type == "digital":
            GPIO.setmode(GPIO.BCM)
            GPIO.setup(self.gpio_pins, GPIO.IN, pull_up_down=GPIO.PUD_DOWN)
        elif self.sensor_type == "analog":
            self.spi = spidev.SpiDev()
            try:
                self.spi.open(0, 0)
                self.spi.max_speed_hz = self.spi_speed
                self.spi.mode = 0
            except Exception as e:
                logging.error(f"Failed to initialize SPI: {e}")
                raise
        else:
            raise ValueError("Invalid sensor_type. Must be 'digital' or 'analog'.")

    def read_sound_level(self):
        if self.sensor_type == "digital":
            try:
                return GPIO.input(self.gpio_pins[0])
            except Exception as e:
                logging.error(f"Error reading digital sound sensor {self.sensor_id}: {e}")
                return None
        elif self.sensor_type == "analog":
            try:
                channel = self.channels[0]
                if not 0 <= channel <= 7:
                    raise ValueError("MCP3008 channel must be 0-7")
                # MCP3008 command: start bit (1), single-ended mode (1), channel bits (3), then dummy byte
                cmd = [1, (8 + channel) << 4, 0]
                reply = self.spi.xfer2(cmd)
                # 10-bit result: bits 0-1 of reply[1] and all 8 bits of reply[2]
                value = ((reply[1] & 3) << 8) + reply[2]
                return value
            except Exception as e:
                logging.error(f"Error reading analog sound sensor {self.sensor_id}: {e}")
                return None
        else:
            return None

    def detect_sound_event(self):
        sound_level = self.read_sound_level()
        if sound_level is None:
            return False
        if self.sensor_type == "digital":
            return sound_level == 1
        elif self.sensor_type == "analog":
            return sound_level >= self.threshold
        else:
            return False

    def run(self):
        self.running = True
        while self.running:
            if self.detect_sound_event():
                timestamp = time.time()
                message = f"Sound event detected by sensor {self.sensor_id} at {timestamp:.2f}"
                try:
                    self.log_queue.put((timestamp, message))
                except queue.Full:
                    logging.warning("Log queue is full. Dropping log message.")
                time.sleep(self.debounce_time)
            time.sleep(1 / self.sample_rate)

    def stop(self):
        self.running = False
        if self.sensor_type == "digital":
            GPIO.cleanup(self.gpio_pins)
        elif self.sensor_type == "analog":
            if self.spi:
                self.spi.close()

def log_messages(log_queue, log_file):
    logging.basicConfig(filename=log_file, level=logging.INFO,
                        format='%(asctime)s - %(levelname)s - %(message)s')
    while True:
        try:
            timestamp, message = log_queue.get(timeout=1)
            logging.info(message)
            log_queue.task_done()
        except queue.Empty:
            continue

def main():
    parser = argparse.ArgumentParser(description="Sound Sensor Monitoring System")
    parser.add_argument("--sensor_type", required=True, choices=["digital", "analog"],
                        help="Type of sound sensor (digital or analog)")
    parser.add_argument("--threshold", type=int, required=True,
                        help="Sound level threshold for analog sensors (0-1023)")
    parser.add_argument("--sample_rate", type=int, required=True,
                        help="Sampling rate in Hz")
    parser.add_argument("--log_file", required=True,
                        help="Path to the log file")
    parser.add_argument("--gpio_pins", type=int, nargs="+",
                        help="GPIO pin numbers for digital sensors (comma-separated)")
    parser.add_argument("--channels", type=int, nargs="+",
                        help="MCP3008 channels for analog sensors (comma-separated)")
    parser.add_argument("--spi_speed", type=int, default=1000000,
                        help="SPI speed in Hz (default: 1000000)")
    parser.add_argument("--sensor_ids", type=str, nargs="+",
                        help="Unique IDs for each sensor (comma-separated)")
    args = parser.parse_args()

    sensor_type = args.sensor_type
    threshold = args.threshold
    sample_rate = args.sample_rate
    log_file = args.log_file
    gpio_pins = args.gpio_pins
    channels = args.channels
    spi_speed = args.spi_speed
    sensor_ids = args.sensor_ids

    if sensor_type == "digital" and gpio_pins is None:
        raise ValueError("GPIO pins must be specified for digital sensors.")
    if sensor_type == "analog" and channels is None:
        raise ValueError("MCP3008 channels must be specified for analog sensors.")
    if len(sensor_ids) != len(gpio_pins) if gpio_pins else len(sensor_ids) != len(channels):
        raise ValueError("Number of sensor IDs must match the number of GPIO pins or channels.")

    log_queue = queue.Queue(maxsize=1000)
    log_thread = threading.Thread(target=log_messages, args=(log_queue, log_file))
    log_thread.daemon = True
    log_thread.start()

    sensors = []
    threads = []
    try:
        for i, sensor_id in enumerate(sensor_ids):
            if gpio_pins:
                sensor = SoundSensor(sensor_id, sensor_type, threshold, sample_rate,
                                     [gpio_pins[i]], [], spi_speed, log_queue)
            else:
                sensor = SoundSensor(sensor_id, sensor_type, threshold, sample_rate,
                                     [], [channels[i]], spi_speed, log_queue)
            sensors.append(sensor)
            thread = threading.Thread(target=sensor.run)
            threads.append(thread)
            thread.start()

        while True:
            time.sleep(1)
    except KeyboardInterrupt:
        print("Shutting down...")
    finally:
        for sensor in sensors:
            sensor.stop()
        for thread in threads:
            thread.join(timeout=2)
        log_queue.join()
        print("Program finished.")

if __name__ == "__main__":
    main()

