    if sensor_type == "analog" and channels is None:
        raise ValueError("MCP3008 channels must be specified for analog sensors.")
    if len(sensor_ids) != len(gpio_pins) if gpio_pins else len(sensor_ids) != len(channels):
        raise ValueError("Number of sensor IDs must match the number of GPIO pins or channels.")

    log_queue = queue.Queue(maxsize=1000)
    log_thread = threading.Thread(target=log_messages, args=(log_queue, log_file))
    log_thread.daemon = True
    log_thread.start()

    sensors = []
    threads = []
    try:
        for i, sensor_id in enumerate(sensor_ids):
            if gpio_pins:
                sensor = SoundSensor(sensor_id, sensor_type, threshold, sample_rate,
                                     [gpio_pins[i]], [], spi_speed, log_queue)
            else:
                sensor = SoundSensor(sensor_id, sensor_type, threshold, sample_rate,
                                     [], [channels[i]], spi_speed, log_queue)
            sensors.append(sensor)
            thread = threading.Thread(target=sensor.run)
            threads.append(thread)
            thread.start()

        while True:
            time.sleep(1)
    except KeyboardInterrupt:
        print("Shutting down...")
    finally:
        for sensor in sensors:
            sensor.stop()
        for thread in threads:
            thread.join(timeout=2)
        log_queue.join()
        print("Program finished.")

if __name__ == "__main__":
    main()

