import cv2
import numpy as np
import time
import logging
import signal
import sys
from picamera2 import Picamera2

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

running = True

def signal_handler(signum, frame):
    global running
    logging.info(f"Signal {signum} received, shutting down gracefully...")
    running = False

def initialize_camera(camera_num):
    try:
        picam2 = Picamera2(camera_num)
        config = picam2.create_preview_configuration(
            main={"size": (640, 480), "format": "RGB888"},
            controls={"FrameDurationLimits": (33333, 33333)}
        )
        picam2.configure(config)
        picam2.start()
        logging.info(f"Camera {camera_num} initialized successfully.")
        return picam2
    except Exception as e:
        logging.error(f"Failed to initialize camera {camera_num}: {e}")
        return None

def capture_frame(picam2):
    try:
        return picam2.capture_array()
    except Exception as e:
        logging.error(f"Failed to capture frame from camera: {e}")
        return None

def display_image(image, window_name):
    try:
        cv2.imshow(window_name, image)
        return cv2.waitKey(30) & 0xFF
    except Exception as e:
        logging.error(f"Error displaying image: {e}")
        return None

def main():
    global running
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    picam2_left = initialize_camera(0)
    picam2_right = initialize_camera(1)

    if picam2_left is None and picam2_right is None:
        logging.error("No cameras initialized. Exiting.")
        sys.exit(1)

    try:
        while running:
            left_image = capture_frame(picam2_left)
            right_image = capture_frame(picam2_right)

            if left_image is None or right_image is None:
                logging.warning("One or more frames failed to capture. Skipping this iteration.")
                continue

            image = np.hstack((left_image, right_image))

            key = display_image(image, 'Dual CSI Cameras')

            if key == 27:
                logging.info("ESC key pressed. Exiting...")
                break

            if cv2.getWindowProperty('Dual CSI Cameras', cv2.WND_PROP_VISIBLE) < 1:
                logging.info("Display window closed. Exiting...")
                break

    except KeyboardInterrupt:
        logging.info("KeyboardInterrupt received. Exiting...")
    finally:
        logging.info("Cleaning up resources...")
        if picam2_left is not None:
            try:
                picam2_left.stop()
                picam2_left.close()
            except Exception as e:
                logging.error(f"Error stopping/closing left camera: {e}")
        if picam2_right is not None:
            try:
                picam2_right.stop()
                picam2_right.close()
            except Exception as e:
                logging.error(f"Error stopping/closing right camera: {e}")
        cv2.destroyAllWindows()
        logging.info("Program finished.")

if __name__ == "__main__":
    main()

