import multiprocessing
import os
import signal
import threading
import time
import atexit
import traceback
from typing import Optional

import setproctitle

from controlevents import CEvent, PostEvent, ConsoleEvent
from config import Config
from logsupport import LogSupport as L
from utils.utilfuncs import disptime


class Watchdog:
    """
    A watchdog process that monitors a separate console process.
    """

    def __init__(self, console_pid: int, keepalive_event: multiprocessing.Event):
        self.console_pid = console_pid
        self.keepalive_event = keepalive_event
        self.running = True
        self.tombstone_path = '/home/pi/.tombstoneW'
        self.history_path = '/home/pi/Console/.HistoryBuffer/hlogW'
        self._lock = threading.Lock()

    # ------------------------------------------------------------------
    # Signal handling
    # ------------------------------------------------------------------
    def _signal_handler(self, signum: int, frame) -> None:
        """Generic signal handler with error handling."""
        try:
            self._handle_signal(signum, frame)
        except Exception as exc:
            self._log_error(f"Unhandled exception in signal handler for signal {signum}: {exc}")

    def _handle_signal(self, signum: int, frame) -> None:
        """Dispatch to the specific handler for the received signal."""
        if signum == signal.SIGTERM:
            self._handle_sigterm()
        elif signum == signal.SIGINT:
            self._handle_sigint()
        elif signum == signal.SIGUSR1:
            self._handle_sigusr1()
        elif signum == signal.SIGHUP:
            self._handle_sighup()
        elif signum == signal.SIGABRT:
            self._handle_sigabort()
        else:
            self._log_debug(f"Received unexpected signal {signum}")

    def _handle_sigterm(self) -> None:
        """Handle SIGTERM (systemd stop)."""
        self._log_debug("Received SIGTERM (systemd stop).")
        self.running = False

    def _handle_sigint(self) -> None:
        """Handle SIGINT (Ctrl-C)."""
        self._log_debug("Received SIGINT (Ctrl-C).")
        self.running = False

    def _handle_sigusr1(self) -> None:
        """Handle SIGUSR1."""
        self._log_debug("Received SIGUSR1.")
        self.running = False

    def _handle_sighup(self) -> None:
        """Handle SIGHUP."""
        self._log_debug("Received SIGHUP.")

    def _handle_sigabort(self) -> None:
        """Handle SIGABRT."""
        self._log_debug("Received SIGABRT.")
        self._write_tombstone(traceback.format_exc())
        os._exit(93)

    # ------------------------------------------------------------------
    # Logging
    # ------------------------------------------------------------------
    def _log_debug(self, message: str) -> None:
        """Append a debug message to the watchdog history file."""
        try:
            with open(self.history_path, 'a') as fh:
                fh.write(f"{disptime()} {message}\n")
                fh.flush()
                os.fsync(fh.fileno())
        except OSError as exc:
            print(f"Error writing to watchdog history: {exc}", file=os.stderr)

    def _log_error(self, message: str) -> None:
        """Log an error message."""
        self._log_debug(f"ERROR: {message}")

    def _write_tombstone(self, message: str) -> None:
        """Write a tombstone with a stack trace to the tombstone file."""
        try:
            with open(self.tombstone_path, 'w') as fh:
                fh.write(f"{disptime()} Watchdog exiting: {message}\n")
                fh.flush()
                os.fsync(fh.fileno())
        except OSError as exc:
            print(f"Error writing to tombstone: {exc}", file=os.stderr)

    # ------------------------------------------------------------------
    # Keepalive injector
    # ------------------------------------------------------------------
    def _keepalive_injector(self) -> None:
        """Periodically post a keepalive event to the console process."""
        while self.running:
            try:
                now = time.time()
                PostEvent(ConsoleEvent(CEvent.FailSafePing, inject=now))
                self._log_debug(f"Keepalive injected at {now}")
            except Exception as exc:
                self._log_error(f"Error injecting keepalive: {exc}")
            time.sleep(30)

    # ------------------------------------------------------------------
    # Main loop
    # ------------------------------------------------------------------
    def run(self) -> None:
        """Main watchdog loop."""
        self._log_debug("Watchdog started")
        setproctitle.setproctitle("Console Watchdog")

        # Register signal handlers
        signal.signal(signal.SIGTERM, self._signal_handler)
        signal.signal(signal.SIGINT, self._signal_handler)
        signal.signal(signal.SIGUSR1, self._signal_handler)
        signal.signal(signal.SIGHUP, self._signal_handler)
        signal.signal(signal.SIGABRT, self._signal_handler)

        # Start the keepalive injector in a daemon thread
        injector_thread = threading.Thread(target=self._keepalive_injector, daemon=True)
        injector_thread.start()

        # Check every 30 seconds that the main thread is alive
        while self.running:
            time.sleep(30)
            if not self._is_main_thread_alive():
                self._log_error("Main thread died. Attempting to restart.")
                self._handle_sigint()
                break

        # Wait for keepalive with a 60-second timeout
        if self.running:
            self._log_debug("Waiting for keepalive...")
            if not self.keepalive_event.wait(timeout=60):
                self._log_error("Keepalive timeout. Console may have crashed.")
                self._handle_sigint()

        # Check if console is still alive
        if self.running and self.console_pid > 0:
            try:
                os.kill(self.console_pid, 0)
            except ProcessLookupError:
                self._log_debug("Console process not found.")
            except PermissionError:
                self._log_debug("Permission denied checking console process.")
            except OSError:
                self._log_debug("Console process not found.")
            else:
                self._log_error("Console process still alive. Sending SIGUSR1.")
                try:
                    os.kill(self.console_pid, signal.SIGUSR1)
                    time.sleep(3)
                    os.kill(self.console_pid, signal.SIGKILL)
                    self._log_debug("Console process killed after SIGUSR1.")
                except ProcessLookupError:
                    self._log_debug("Console process not found after SIGUSR1.")
                except PermissionError:
                    self._log_debug("Permission denied sending signals to console.")
                except OSError:
