                    time.sleep(3)
                    os.kill(Config.sysStore.Console_pid, signal.SIGKILL)
                except ProcessLookupError:
                    pass
                except PermissionError:
                    pass
                except OSError:
                    pass
    except Exception as exc:
        print(f"atexit handler error: {exc}", file=os.stderr)


def main() -> None:
    """Entry point for the watchdog process."""
    # Register atexit handler
    atexit.register(_atexit_handler)

    # Initialize logging
    L.Logs.Init()
    L.Logs.Log("Watchdog starting", severity=L.ConsoleDetailHigh)

    # Get console PID from config
    console_pid = getattr(Config.sysStore, 'Console_pid', 0)
    if console_pid <= 0:
        L.Logs.Log("Console PID not set in config.sysStore.Console_pid", severity=L.ConsoleError)
        os._exit(94)

    # Create and run the watchdog
    keepalive_event = multiprocessing.Event()
    watchdog = Watchdog(console_pid, keepalive_event)
