import atexit
import logging
import signal
import threading
import time
from typing import Tuple, Optional

from flask import Flask, render_template, Response, request

import config
import mail_config

try:
    from picamera2 import Picamera2
except ImportError:
    print("Error: picamera2 library is not installed. Install with: pip install picamera2")
    raise

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

app = Flask(__name__)

output_frame = None
frame_lock = threading.Lock()
picam2: Optional[Picamera2] = None
last_email_time = 0.0
shutdown_event = threading.Event()


class Camera:
    def __init__(self):
        global picam2
        try:
            picam2 = Picamera2()
            # Configure for JPEG streaming at 640x480
            config_cam = picam2.create_video_configuration(
                main={"size": (640, 480), "format": "RGB888"},
                transform=None  # Apply vertical flip via transform options
            )
            picam2.configure(config_cam)
            picam2.start()
            logging.info("Camera initialized successfully.")
        except Exception as e:
            logging.error(f"Error initializing camera: {e}")
            raise

    def get_frame(self) -> bytes:
        """Captures a frame and returns it as JPEG bytes."""
        global picam2
        if picam2 is None:
            raise RuntimeError("Camera not initialized.")
        try:
            frame = picam2.capture_array()
            # picamera2 returns RGB; convert to JPEG bytes
            from PIL import Image
            import io
            img = Image.fromarray(frame)
            buf = io.BytesIO()
            img.save(buf, format='JPEG')
            return buf.getvalue()
        except Exception as e:
            logging.error(f"Error capturing frame: {e}")
            return b""

    def get_object(self, classifier) -> Tuple[bytes, bool]:
        """Detects objects using the given classifier and returns the frame and detection status."""
        try:
            frame = self.get_frame()
            if frame:
                with frame_lock:
                    output_frame = frame.copy()
                detection_status = classifier.detect_object(frame)
                return frame, detection_status
            return b"", False
        except Exception as e:
            logging.error(f"Error in object detection: {e}")
            return b"", False

    def get_object_with_basic_motion_detection(self) -> Tuple[bytes, bool]:
        """Detects objects using basic motion detection and returns the frame and detection status."""
        try:
            frame = self.get_frame()
            if frame:
                with frame_lock:
                    output_frame = frame.copy()
                detection_status = config.motion_detector.detect_motion(frame)
                return frame, detection_status
            return b"", False
        except Exception as e:
            logging.error(f"Error in motion detection: {e}")
            return b"", False

    def close(self):
        """Releases camera resources."""
        global picam2
        if picam2 is not None:
            try:
                picam2.stop()
                picam2.close()
                logging.info("Camera resources released.")
            except Exception as e:
                logging.error(f"Error releasing camera: {e}")
            finally:
                picam2 = None


def check_for_objects():
    """Continuously checks for objects and sends email notifications."""
    global last_email_time
    while not shutdown_event.is_set():
        try:
            if config.classifier_name == 'motion_detector':
                frame, detected = camera.get_object_with_basic_motion_detection()
            else:
                frame, detected = camera.get_object(config.classifier)

            if detected:
                if config.send_email_notifications:
                    current_time = time.time()
                    if current_time - last_email_time >= config.email_send_interval:
                        try:
                            mail_config.send_email(frame, config)
                            last_email_time = current_time
                            logging.info("Email notification sent successfully.")
                        except Exception as e:
                            logging.error(f"Error sending email notification: {e}")
                else:
                    logging.info("Object detected, but email notifications are disabled.")
        except Exception as e:
            logging.error(f"Error in object detection loop: {e}")
        shutdown_event.wait(1)


def gen(camera: Camera):
    """Generates frames for the video feed."""
    while not shutdown_event.is_set():
        try:
            with frame_lock:
                if output_frame is None:
                    time.sleep(0.1)
                    continue
                frame = output_frame.copy()

            yield (b'--frame\r\n'
                   b'Content-Type: image/jpeg\r\n\r\n' + frame + b'\r\n\r\n')
        except Exception as e:
            logging.error(f"Error generating frame: {e}")
            shutdown_event.wait(0.1)


@app.route('/', methods=['GET', 'POST'])
def index():
    """Handles the main page and form submission."""
    if request.method == 'POST':
        config.set_classifier(request.form.get('classifier'))
        config.set_send_email_notifications(request.form.get('send_email_notifications') == 'on')
        config.set_email_address(request.form.get('email_address'))
        config.set_live_preview(request.form.get('live_preview') == 'on')
        config.set_email_send_interval(int(request.form.get('email_send_interval', 30)))
        logging.info("Configuration updated.")

    return render_template(
        'index.html',
        classifiers=config.classifierNameLocationDict,
        selected_classifier=config.classifier_name,
        send_email_notifications=config.send_email_notifications,
        email_address=config.email_address,
        live_preview=config.live_preview,
        email_send_interval=config.email_send_interval
    )


@app.route('/video_feed')
def video_feed():
    """Provides the video feed."""
    return Response(gen(camera), mimetype='multipart/x-mixed-replace; boundary=frame')


def cleanup(signum=None, frame=None):
    """Clean up resources on exit."""
    logging.info("Shutting down...")
    shutdown_event.set()
    if camera:
        camera.close()
    logging.info("Cleanup complete.")


if __name__ == '__main__':
    try:
        camera = Camera()
    except Exception:
        print("Failed to initialize camera. Exiting.")
        exit(1)

    atexit.register(cleanup)
    signal.signal(signal.SIGINT, cleanup)
    signal.signal(signal.SIGTERM, cleanup)

    object_detection_thread = threading.Thread(target=check_for_objects, daemon=True)
    object_detection_thread.start()

    try:
        app.run(host='0.0.0.0', debug=False, threaded=True)
    except Exception as e:
        logging.error(f"Flask server error: {e}")
    finally:
        cleanup()

