import json
import logging
import os
import signal
import statistics
import sys
import time
from datetime import datetime

try:
    from gpiozero import OutputDevice, InputDevice
    from gpiozero.exc import GPIOZeroError, DeviceClosed
except ImportError:
    OutputDevice = None
    InputDevice = None
    GPIOZeroError = Exception
    DeviceClosed = Exception

DEFAULT_CONFIG = {
    "sensors": [
        {"trigger_pin": 17, "echo_pin": 18, "offset": 0.0, "max_distance": 200.0},
        {"trigger_pin": 22, "echo_pin": 23, "offset": 0.0, "max_distance": 200.0},
        {"trigger_pin": 24, "echo_pin": 25, "offset": 0.0, "max_distance": 200.0},
    ],
    "alert_threshold_low": 10.0,
    "alert_threshold_high": 180.0,
    "alert_repeat_delay": 60,
    "log_file": "water_level.log",
}

running = True


def signal_handler(signum, frame):
    global running
    running = False


def load_config(config_file="config.json"):
    try:
        with open(config_file, "r") as f:
            config = json.load(f)
        if not isinstance(config, dict):
            raise ValueError("Config must be a JSON object")
        if "sensors" not in config or not isinstance(config["sensors"], list):
            raise ValueError("Config must contain a 'sensors' list")
        for idx, sensor in enumerate(config["sensors"]):
            if not isinstance(sensor, dict):
                raise ValueError(f"Sensor {idx} must be an object")
            required = ["trigger_pin", "echo_pin", "offset", "max_distance"]
            for key in required:
                if key not in sensor:
                    raise ValueError(f"Sensor {idx} missing required key '{key}'")
            if not isinstance(sensor["trigger_pin"], int) or sensor["trigger_pin"] < 0:
                raise ValueError(f"Sensor {idx} trigger_pin must be a non-negative integer")
            if not isinstance(sensor["echo_pin"], int) or sensor["echo_pin"] < 0:
                raise ValueError(f"Sensor {idx} echo_pin must be a non-negative integer")
            if not isinstance(sensor["offset"], (int, float)):
                raise ValueError(f"Sensor {idx} offset must be a number")
            if not isinstance(sensor["max_distance"], (int, float)) or sensor["max_distance"] <= 0:
                raise ValueError(f"Sensor {idx} max_distance must be a positive number")
        if "alert_threshold_low" not in config or not isinstance(config["alert_threshold_low"], (int, float)):
            raise ValueError("alert_threshold_low must be a number")
        if "alert_threshold_high" not in config or not isinstance(config["alert_threshold_high"], (int, float)):
            raise ValueError("alert_threshold_high must be a number")
        if "alert_repeat_delay" not in config or not isinstance(config["alert_repeat_delay"], int) or config["alert_repeat_delay"] < 0:
            raise ValueError("alert_repeat_delay must be a non-negative integer")
        if "log_file" not in config or not isinstance(config["log_file"], str):
            raise ValueError("log_file must be a string")
        return config
    except FileNotFoundError:
        logging.warning("config.json not found; using default configuration.")
        return DEFAULT_CONFIG.copy()
