#!/usr/bin/env python3

import RPi.GPIO as GPIO
import time
import speech_recognition as sr
import os
import sys
import signal
import random
from datetime import datetime

# Configuration
LIGHT_PIN = 17
DHT_PIN = 4
WAKE_WORD = "Greenhouse"

# Global state for cleanup
gpio_available = False
camera_available = False
dht_available = False
picam2 = None

# Initialize GPIO
try:
    GPIO.setmode(GPIO.BCM)
    GPIO.setup(LIGHT_PIN, GPIO.OUT, initial=GPIO.LOW)
    gpio_available = True
    print("GPIO initialized successfully.")
except Exception as e:
    print(f"GPIO initialization failed: {e}. Running in simulation mode.")
    gpio_available = False

# Initialize DHT11 sensor
try:
    import adafruit_dht
    dht_device = adafruit_dht.DHT11(DHT_PIN, use_pulseio=False)
    dht_available = True
    print("DHT11 sensor initialized successfully.")
except ImportError:
    print("adafruit_dht library not found. Running in simulation mode.")
    dht_available = False
except Exception as e:
    print(f"DHT11 initialization failed: {e}. Running in simulation mode.")
    dht_available = False

# Initialize camera
try:
    from picamera2 import Picamera2
    picam2 = Picamera2()
    config = picam2.create_still_configuration(main={"size": (640, 480)})
    picam2.configure(config)
    picam2.start()
    camera_available = True
    print("Camera initialized successfully.")
except ImportError:
    print("picamera2 library not found. Running in simulation mode.")
    camera_available = False
except Exception as e:
    print(f"Camera initialization failed: {e}. Running in simulation mode.")
    camera_available = False

def turn_lights_on():
    """Turn on the greenhouse lights."""
    if gpio_available:
        try:
            GPIO.output(LIGHT_PIN, GPIO.HIGH)
            print("Lights turned on.")
        except Exception as e:
            print(f"Error turning on lights: {e}")
    else:
        print("Simulating lights on.")

def turn_lights_off():
    """Turn off the greenhouse lights."""
    if gpio_available:
        try:
            GPIO.output(LIGHT_PIN, GPIO.LOW)
            print("Lights turned off.")
        except Exception as e:
            print(f"Error turning off lights: {e}")
    else:
        print("Simulating lights off.")

def read_temperature():
    """Read temperature from DHT11 sensor or simulate."""
    if dht_available:
        try:
            temperature = dht_device.temperature
            if temperature is not None:
                return temperature
            else:
                print("DHT11 returned None temperature.")
        except RuntimeError as e:
            print(f"DHT11 read error (checksum or timeout): {e}")
        except Exception as e:
            print(f"DHT11 unexpected error: {e}")
    # Fallback to simulation
    temperature = random.uniform(15, 35)
    print(f"Simulating temperature: {temperature:.1f}°C")
    return temperature

def capture_image():
    """Capture an image using the camera."""
    if camera_available:
        try:
            timestamp = datetime.now().strftime("%Y%m%d_%H%M%S")
            filename = f"greenhouse_{timestamp}.jpg"
            picam2.capture_file(filename)
            print(f"Image captured: {filename}")
        except Exception as e:
            print(f"Error capturing image: {e}")
    else:
        print("Simulating image capture.")

def cleanup():
    """Clean up resources."""
    print("Cleaning up...")
    if gpio_available:
        try:
            GPIO.cleanup()
            print("GPIO cleaned up.")
        except Exception as e:
            print(f"Error cleaning up GPIO: {e}")
    if camera_available:
        try:
            picam2.stop()
            picam2.close()
            print("Camera closed.")
        except Exception as e:
            print(f"Error closing camera: {e}")
    if dht_available:
        try:
            dht_device.exit()
            print("DHT11 sensor closed.")
        except Exception as e:
            print(f"Error closing DHT11: {e}")
    print("Cleanup complete.")

def signal_handler(sig, frame):
    """Handle termination signals."""
    print(f"Received signal {sig}. Exiting...")
    cleanup()
    sys.exit(0)

# Register signal handlers
signal.signal(signal.SIGINT, signal_handler)
signal.signal(signal.SIGTERM, signal_handler)

def main():
    """Main loop for voice control."""
    recognizer = sr.Recognizer()
    try:
        with sr.Microphone() as source:
            print("Say 'Greenhouse' to start...")
            recognizer.adjust_for_ambient_noise(source, duration=1)
            while True:
                audio = recognizer.listen(source, timeout=5, phrase_time_limit=5)
                try:
                    text = recognizer.recognize_google(audio).lower()
                    print(f"You said: {text}")
                    if WAKE_WORD in text:
                        if "turn on the lights" in text:
                            turn_lights_on()
                        elif "turn off the lights" in text:
                            turn_lights_off()
                        elif "what is the temperature" in text:
                            temperature = read_temperature()
                            print(f"Temperature: {temperature:.1f}°C")
                        elif "take a picture" in text:
                            capture_image()
                except sr.UnknownValueError:
                    print("Could not understand audio")
                except sr.RequestError as e:
                    print(f"Could not request results from Google Speech Recognition service; {e}")
    except Exception as e:
        print(f"Microphone error: {e}")
    finally:
        cleanup()

if __name__ == "__main__":
    main()

