import pygame.mixer
from gpiozero import Button, OutputDevice
import cv2
import face
import config

# ---------------------------------------------------------------------------
# Globals for cleanup
# ---------------------------------------------------------------------------
_camera = None
_door = None
_button = None
_running = True


def _cleanup():
    """Release all hardware resources."""
    global _camera, _door, _button
    if _camera is not None:
        try:
            _camera.release()
        except Exception:
            pass
        _camera = None
    if _door is not None:
        try:
            _door.cleanup()
        except Exception:
            pass
        _door = None
    if _button is not None:
        try:
            _button.close()
        except Exception:
            pass
        _button = None
    try:
        pygame.mixer.quit()
    except Exception:
        pass


def _signal_handler(signum, frame):
    """Handle SIGINT / SIGTERM for graceful shutdown."""
    global _running
    _running = False


def _load_sounds():
    """Load three pygame.mixer.Sound objects and assign them to channels 0, 1, 2."""
    sounds = {}
    for name, path in (
        ("welcome", config.WELCOME_SOUND_PATH),
        ("wait", config.WAIT_SOUND_PATH),
        ("later", config.LATER_SOUND_PATH),
    ):
        try:
            sounds[name] = pygame.mixer.Sound(path)
        except pygame.error as exc:
            print(f"Error loading sound '{name}' from {path}: {exc}", file=sys.stderr)
            raise
    return sounds


def _load_model():
    """Load the pre-trained EigenFace model and verify the file exists."""
    if not hasattr(config, "TRAINING_FILE") or not config.TRAINING_FILE:
        raise ValueError("config.TRAINING_FILE is not set")
    if not hasattr(config, "POSITIVE_LABEL") or config.POSITIVE_LABEL is None:
        raise ValueError("config.POSITIVE_LABEL is not set")
    if not hasattr(config, "POSITIVE_THRESHOLD") or config.POSITIVE_THRESHOLD is None:
        raise ValueError("config.POSITIVE_THRESHOLD is not set")
