        raise ValueError("config.NEGATIVE_LABEL is not set")
    if not hasattr(config, "NEGATIVE_THRESHOLD") or config.NEGATIVE_THRESHOLD is None:
        raise ValueError("config.NEGATIVE_THRESHOLD is not set")
    if not hasattr(config, "UNKNOWN_LABEL") or config.UNKNOWN_LABEL is None:
        raise ValueError("config.UNKNOWN_LABEL is not set")
    if not hasattr(config, "UNKNOWN_THRESHOLD") or config.UNKNOWN_THRESHOLD is None:
        raise ValueError("config.UNKNOWN_THRESHOLD is not set")
    if not hasattr(config, "FACE_WIDTH") or config.FACE_WIDTH is None:
        raise ValueError("config.FACE_WIDTH is not set")
    if not hasattr(config, "FACE_HEIGHT") or config.FACE_HEIGHT is None:
        raise ValueError("config.FACE_HEIGHT is not set")
    if not hasattr(config, "IMAGE_WIDTH") or config.IMAGE_WIDTH is None:
        raise ValueError("config.IMAGE_WIDTH is not set")
    if not hasattr(config, "IMAGE_HEIGHT") or config.IMAGE_HEIGHT is None:
        raise ValueError("config.IMAGE_HEIGHT is not set")
    if not hasattr(config, "SCALE_FACTOR") or config.SCALE_FACTOR is None:
        raise ValueError("config.SCALE_FACTOR is not set")
    if not hasattr(config, "MIN_NEIGHBORS") or config.MIN_NEIGHBORS is None:
        raise ValueError("config.MIN_NEIGHBORS is not set")
    if not hasattr(config, "MIN_SIZE") or config.MIN_SIZE is None:
        raise ValueError("config.MIN_SIZE is not set")
    if not hasattr(config, "CASCADE_PATH") or not config.CASCADE_PATH:
        raise ValueError("config.CASCADE_PATH is not set")
    if not hasattr(config, "POSITIVE_THRESHOLD") or config.POSITIVE_THRESHOLD is None:
        raise ValueError("config.POSITIVE_THRESHOLD is not set")
    if not hasattr(config, "POSITIVE_LABEL") or config.POSITIVE_LABEL is None:
        raise ValueError("config.POSITIVE_LABEL is not set")
    if not hasattr(config, "NEGATIVE_THRESHOLD") or config.NEGATIVE_THRESHOLD is None:
        raise ValueError("config.NEGATIVE_THRESHOLD is not set")
    if not hasattr(config, "NEGATIVE_LABEL") or config.NEGATIVE_LABEL is None:
        raise ValueError("config.NEGATIVE_LABEL is not set")
    if not hasattr(config, "UNKNOWN_THRESHOLD") or config.UNKNOWN_THRESHOLD is None:
        raise ValueError("config.UNKNOWN_THRESHOLD is not set")
    if not hasattr(config, "UNKNOWN_LABEL") or config.UNKNOWN_LABEL is None:
        raise ValueError("config.UNKNOWN_LABEL is not set")

    if not os.path.isfile(config.TRAINING_FILE):
        raise FileNotFoundError(f"Training file not found: {config.TRAINING_FILE}")
    model = cv2.face.EigenFaceRecognizer_create()
    model.read(config.TRAINING_FILE)
    return model


def _is_recognised(image, model):
    """Detect a single face, crop and resize it, then predict with the model."""
    gray_image = cv2.cvtColor(image, cv2.COLOR_BGR2GRAY)
    face_coords = face.detect_single(gray_image)
    if face_coords is None:
        return False, None
    x, y, w, h = face_coords
    cropped_face = face.crop(gray_image, x, y, w, h)
    resized_face = face.resize(cropped_face)
    label, confidence = model.predict(resized_face)
    return label == config.POSITIVE_LABEL and confidence < config.POSITIVE_THRESHOLD, confidence


