    except Exception as exc:
        print(f"Error loading model: {exc}", file=sys.stderr)
        _cleanup()
        sys.exit(1)

    # --- Initialise door hardware ----------------------------------------
    try:
        _door = hardware.Door()
    except Exception as exc:
        print(f"Error initialising door hardware: {exc}", file=sys.stderr)
        _cleanup()
        sys.exit(1)

    # --- Initialise button hardware -------------------------------------
    try:
        _button = Button(5, pull_up=True)
    except Exception as exc:
        print(f"Error initialising button on GPIO 5: {exc}", file=sys.stderr)
        _cleanup()
        sys.exit(1)

    # --- Initialise camera ----------------------------------------------
    try:
        _camera = config.get_camera()
    except Exception as exc:
        print(f"Error initialising camera: {exc}", file=sys.stderr)
        _cleanup()
        sys.exit(1)

    # --- Main loop -------------------------------------------------------
    try:
        while _running:
            # Check door button every 0.1 s
            if _button.is_pressed:
                print("Button pressed, looking for face...")
                try:
                    ret, image = _camera.read()
                    if not ret or image is None:
                        print("Error: could not read frame from camera", file=sys.stderr)
                        time.sleep(0.5)
                        continue

                    recognised, confidence = _is_recognised(image, model)

                    if recognised:
                        print("Recognised face! Unlocking door...")
                        _door.unlock()
                        sounds["welcome"].play(channel=0)
                    else:
                        print("Face not recognised.")
                        sounds["later"].play(channel=1)
                        time.sleep(1)
                        sounds["wait"].play(channel=2)

                except cv2.error as exc:
                    print(f"OpenCV error during face recognition: {exc}", file=sys.stderr)
                except Exception as exc:
                    print(f"Unexpected error during face recognition: {exc}", file=sys.stderr)

            # Manual lock via stdin
            if sys.stdin in select.select([sys.stdin], [], [], 0)[0]:
                line = sys.stdin.readline().strip().lower()
                if line == "l":
                    print("Manual lock requested.")
                    _door.lock()

            time.sleep(0.1)

    except Exception as exc:
        print(f"Fatal error in main loop: {exc}", file=sys.stderr)
    finally:
        _cleanup()


if __name__ == "__main__":
    import os
    import select
    import hardware
    main()

