import signal
import sys
import numpy as np
import sounddevice as sd
from gpiozero import Button

BUTTON_PIN = 5
SAMPLE_RATE = 44100
BLOCK_SIZE = 1024
CHANNELS = 1

gain = 1.0
button = None
stream = None
running = True


def apply_distortion(input_data, gain_value):
    """Apply soft-clipping tanh distortion to a mono audio block."""
    return np.tanh(input_data * gain_value)


def audio_callback(indata, outdata, frames, time_info, status):
    """Full-duplex audio callback: apply gain and distortion to input."""
    if status:
        print(f"Audio stream status: {status}", file=sys.stderr)
    try:
        outdata[:] = apply_distortion(indata, gain)
    except Exception as exc:
        print(f"Audio processing error: {exc}", file=sys.stderr)
        outdata[:] = indata


def button_pressed():
    """Toggle gain between 1.0 and 2.0 on each button press."""
    global gain
    gain = 2.0 if gain == 1.0 else 1.0
    print(f"Gain set to {gain}")


def cleanup():
    """Release audio stream and GPIO resources."""
    global stream, button
    if stream is not None:
        try:
            if stream.active:
                stream.stop()
        except Exception:
            pass
        try:
            stream.close()
        except Exception:
            pass
        stream = None
    if button is not None:
        try:
            button.close()
        except Exception:
            pass
        button = None
    print("Resources released.")


def signal_handler(signum, frame):
    """Handle SIGINT/SIGTERM for clean shutdown."""
    global running
    print(f"\nReceived signal {signum}, shutting down...")
    running = False


def main():
    global button, stream

    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    try:
        button = Button(BUTTON_PIN, pull_up=True, bounce_time=0.2)
        button.when_pressed = button_pressed
    except Exception as exc:
        print(f"Failed to initialize button on GPIO {BUTTON_PIN}: {exc}", file=sys.stderr)
        sys.exit(1)

    try:
        stream = sd.Stream(
            samplerate=SAMPLE_RATE,
            blocksize=BLOCK_SIZE,
            channels=CHANNELS,
            dtype='float32',
            callback=audio_callback,
        )
        stream.start()
        print("Audio stream started. Press Ctrl+C to exit.")
        while running:
            signal.pause()
    except sd.PortAudioError as exc:
        print(f"Audio device error: {exc}", file=sys.stderr)
    except Exception as exc:
        print(f"Unexpected error: {exc}", file=sys.stderr)
    finally:
        cleanup()


if __name__ == "__main__":
    main()

