import io
import logging
import numpy as np
import cv2

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')
logger = logging.getLogger(__name__)


class CameraStreamBuffer:
    """
    Accumulates MJPEG bytes from picamera2 and flushes complete frames
    (not I-frames) to an output sink.
    """

    def __init__(self, c):
        if c is None:
            raise ValueError("picamera2 instance c must not be None")
        self.c = c
        self.b = io.BytesIO()
        self.frame_complete = False
        self.frame_type = None

    def write(self, d):
        if not d:
            return
        try:
            self.b.write(d)
            if self.frame_complete:
                self.b.seek(0)
                try:
                    # picamera2 metadata is available via c.current_configuration()
                    meta = self.c.current_configuration()
                    if meta and 'encode' in meta:
                        frame_info = meta['encode']
                        if frame_info and 'frame_type' in frame_info:
                            self.frame_type = frame_info['frame_type']
                except Exception as e:
                    logger.warning("Could not read frame metadata: %s", e)
                    self.frame_type = None

                if self.frame_type is not None and self.frame_type != 1:
                    # Complete frame, not I-frame; flush to sink
                    try:
                        sink = self.c.get_output_sink()
                        if sink:
                            sink.output = self.b.getvalue()
                    except Exception as e:
                        logger.error("Error writing frame to sink: %s", e)
                self.b.seek(0)
                self.b.truncate()
                self.frame_complete = False
        except Exception as e:
            logger.error("Error in CameraStreamBuffer: %s", e)

    def flush(self):
        try:
            self.b.flush()
        except Exception as e:
            logger.error("Error flushing CameraStreamBuffer: %s", e)


class MotionDetectionBuffer:
    """
    Parses MJPEG byte stream for JPEG frames and invokes a callback
    f(previous_frame, current_frame) on each new frame (excluding the
    first frame).
    """

    def __init__(self, f):
        if f is None:
            raise ValueError("Callback f must not be None")
        self.f = f
        self.b = io.BytesIO()
        self.previous_frame = None
        self.first_frame = True

    def write(self, d):
        if not d:
            return
        try:
            self.b.write(d)
            if d.startswith(b'\xff\xd8'):
                # Start of new JPEG frame
                self.b.seek(0)
                data = self.b.read()
                self.b.seek(0)
                self.b.truncate()

                if data:
                    try:
                        arr = np.frombuffer(data, dtype=np.uint8)
                        frame = cv2.imdecode(arr, cv2.IMREAD_COLOR)
                        if frame is None:
                            logger.warning("cv2.imdecode returned None; skipping frame")
                            return

                        if not self.first_frame:
                            self.f(self.previous_frame, frame)
                        self.previous_frame = frame
                        self.first_frame = False
                    except Exception as e:
                        logger.error("Error decoding/processing frame: %s", e)
        except Exception as e:
            logger.error("Error in MotionDetectionBuffer: %s", e)

    def flush(self):
        try:
            self.b.flush()
        except Exception as e:
            logger.error("Error flushing MotionDetectionBuffer: %s", e)

