import signal
import sys
import time
import logging

import cv2
import pygame.mixer
from gpiozero import Button, OutputDevice
from picamera2 import Picamera2

import config
import face

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')
logger = logging.getLogger(__name__)

DOOR_PIN = 18
BUTTON_PIN = 17

_running = True


def _signal_handler(signum, frame):
    global _running
    logger.info('Signal %s received, shutting down...', signum)
    _running = False


def load_sounds():
    try:
        welcome = pygame.mixer.Sound('welcome.wav')
        wait = pygame.mixer.Sound('wait.wav')
        later = pygame.mixer.Sound('later.wav')
        return welcome, wait, later
    except pygame.error as e:
        logger.error('Failed to load sounds: %s', e)
        raise


def init_camera():
    try:
        picam2 = Picamera2()
        picam2.configure(picam2.create_preview_configuration(main={'format': 'BGR888', 'size': (640, 480)}))
        picam2.start()
        return picam2
    except Exception as e:
        logger.error('Failed to initialize camera: %s', e)
        raise


def init_mixer():
    try:
        pygame.mixer.init(frequency=48000, size=-16, channels=2, buffer=1024)
        return pygame.mixer.Sound(1000, -16, 2, 48000)
    except pygame.error as e:
        logger.error('Failed to initialize mixer: %s', e)
        raise


def init_face_recognizer():
    try:
        recognizer = cv2.face.EigenFaceRecognizer_create()
        recognizer.read(config.TRAINING_FILE)
        return recognizer
    except cv2.error as e:
        logger.error('Failed to load training data: %s', e)
        raise


def main():
    global _running

    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    try:
        welcome, wait, later = load_sounds()
    except Exception:
        sys.exit(1)

    try:
        sound_channel = init_mixer()
    except Exception:
        sys.exit(1)

    try:
        picam2 = init_camera()
    except Exception:
        sys.exit(1)

    try:
        recognizer = init_face_recognizer()
    except Exception:
        picam2.close()
        sys.exit(1)

    try:
        door = OutputDevice(DOOR_PIN, active_high=True, initial_value=False)
        button = Button(BUTTON_PIN, pull_up=True)
    except Exception as e:
        logger.error('Failed to initialize GPIO: %s', e)
        picam2.close()
        sys.exit(1)

    logger.info('Door controller started. Press the button to trigger face recognition.')

    try:
        while _running:
            if button.is_button_up():
                logger.info('Button pressed, looking for face...')
                try:
                    image = picam2.capture_array()
                except Exception as e:
                    logger.error('Camera capture failed: %s', e)
                    time.sleep(0.1)
                    continue

                if image is None:
                    logger.warning('Empty frame received.')
                    time.sleep(0.1)
                    continue

                gray_image = cv2.cvtColor(image, cv2.COLOR_BGR2GRAY)
                face_coords = face.detect_single(gray_image)

                if face_coords is None:
                    logger.info('No face detected.')
                    sound_channel.play(later)
                else:
                    x, y, w, h = face_coords
                    cropped_face = face.crop(gray_image, x, y, w, h)
                    resized_face = face.resize(cropped_face)

                    label, confidence = recognizer.predict(resized_face)
                    logger.info('Predicted label: %s, Confidence: %s', label, confidence)

                    if label == config.POSITIVE_LABEL and confidence < config.POSITIVE_THRESHOLD:
                        logger.info('Recognized face! Unlocking door.')
                        door.on()
                        sound_channel.play(welcome)
                        time.sleep(2)
                        door.off()
                    else:
                        logger.info('Face not recognized.')
                        sound_channel.play(wait)

            time.sleep(0.1)

    except Exception as e:
        logger.exception('Unexpected error in main loop: %s', e)
    finally:
        logger.info('Cleaning up resources...')
        try:
            door.off()
            door.close()
            button.close()
        except Exception:
            pass
        try:
            picam2.close()
        except Exception:
            pass
        try:
            pygame.mixer.quit()
        except Exception:
            pass
        logger.info('Shutdown complete.')


if __name__ == '__main__':
    main()

