import os
import time
import signal
import logging
import sys
from PIL import Image, ImageOps
from luma.core.interface.serial import i2c
from luma.oled.device import ssd1306
from luma.core.render import canvas

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

OLED_WIDTH = 128
OLED_HEIGHT = 64
I2C_PORT = 1
I2C_ADDRESS = 0x3C
GIF_FOLDER = "gifs"

running = True

def signal_handler(sig, frame):
    global running
    running = False
    logging.info("SIGINT received, shutting down...")

def initialize_oled():
    try:
        serial = i2c(port=I2C_PORT, address=I2C_ADDRESS)
        device = ssd1306(serial, width=OLED_WIDTH, height=OLED_HEIGHT)
        logging.info("OLED display initialized successfully.")
        return device
    except Exception as e:
        logging.error(f"Failed to initialize OLED display: {e}")
        return None

def load_gif_files(folder_path):
    if not os.path.isdir(folder_path):
        logging.error(f"Folder not found: {folder_path}")
        return []
    gif_files = [f for f in os.listdir(folder_path) if f.lower().endswith('.gif')]
    if not gif_files:
        logging.warning(f"No GIF files found in folder: {folder_path}")
    return gif_files

