import time
import logging
import signal
import sys
from smbus2 import SMBus, i2c_msg

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')
logger = logging.getLogger(__name__)


class DHT20:
    """Driver for the Aosong DHT20 temperature and humidity sensor over I2C."""

    I2C_BUS = 1
    I2C_ADDRESS = 0x38
    STATUS_REG = 0x71
    MEASURE_REG = 0xAC
    MEASURE_CMD = [0x33, 0x00]
    POWER_ON_DELAY = 0.5
    RETRY_DELAY = 2.0
    MAX_RETRIES = 5
    CRC_POLYNOMIAL = 0x31
    CRC_INIT = 0xFF

    def __init__(self, bus_num=I2C_BUS, address=I2C_ADDRESS):
        self.address = address
        self.bus = None
        self._running = True
        try:
            self.bus = SMBus(bus_num)
            time.sleep(self.POWER_ON_DELAY)
            if not self._check_status():
                raise RuntimeError("DHT20 not detected or status check failed")
            logger.info("DHT20 initialized successfully on bus %d at address 0x%02X", bus_num, address)
        except Exception as e:
            logger.error("Failed to initialize DHT20: %s", e)
            self.close()
            raise

    def _check_status(self):
        try:
            status = self.bus.read_byte_data(self.address, self.STATUS_REG)
            if (status & 0x18) != 0x18:
                logger.error("DHT20 status check failed: status byte 0x%02X", status)
                return False
            return True
        except OSError as e:
            logger.error("I2C bus error during status check: %s", e)
            return False

    def _calculate_crc8(self, data):
        crc = self.CRC_INIT
        for byte in data:
            crc ^= byte
            for _ in range(8):
                if crc & 0x80:
                    crc = ((crc << 1) ^ self.CRC_POLYNOMIAL) & 0xFF
                else:
                    crc = (crc << 1) & 0xFF
        return crc

    def _trigger_measurement(self):
        try:
            write_msg = i2c_msg.write(self.address, self.MEASURE_CMD)
            self.bus.i2c_rdwr(write_msg)
            return True
        except OSError as e:
            logger.error("I2C bus error triggering measurement: %s", e)
            return False

    def _read_measurement(self):
        try:
            read_msg = i2c_msg.read(self.address, 7)
            self.bus.i2c_rdwr(read_msg)
            data = list(read_msg)
            if len(data) != 7:
                logger.error("Unexpected data length from DHT20: %d", len(data))
                return None
            crc_received = data[6]
            crc_calculated = self._calculate_crc8(data[:6])
            if crc_calculated != crc_received:
                logger.warning("CRC mismatch: calculated 0x%02X, received 0x%02X", crc_calculated, crc_received)
                return None
            raw_humidity = ((data[1] << 12) | (data[2] << 4) | (data[3] >> 4)) & 0xFFFFF
            raw_temperature = (((data[3] & 0x0F) << 16) | (data[4] << 8) | data[5]) & 0xFFFFF
            temperature = raw_temperature / 5242.88 - 50.0
            humidity = raw_humidity / 1048576.0 * 100.0
            return temperature, humidity
        except OSError as e:
            logger.error("I2C bus error reading measurement: %s", e)
            return None

    def get_temperature_and_humidity(self):
        for attempt in range(1, self.MAX_RETRIES + 1):
            if not self._trigger_measurement():
                logger.warning("Measurement trigger failed on attempt %d/%d", attempt, self.MAX_RETRIES)
                if attempt < self.MAX_RETRIES:
                    time.sleep(self.RETRY_DELAY)
                continue
            timeout = time.time() + 0.1
            while time.time() < timeout:
                try:
                    status = self.bus.read_byte_data(self.address, self.STATUS_REG)
                    if (status & 0x80) == 0:
                        break
                except OSError as e:
                    logger.error("I2C bus error polling status: %s", e)
                    return None, None, True
                time.sleep(0.01)
            else:
                logger.warning("Measurement timeout on attempt %d/%d", attempt, self.MAX_RETRIES)
                if attempt < self.MAX_RETRIES:
                    time.sleep(self.RETRY_DELAY)
                continue
            result = self._read_measurement()
            if result is not None:
                temperature, humidity = result
                return temperature, humidity, False
            logger.warning("Measurement read failed on attempt %d/%d", attempt, self.MAX_RETRIES)
            if attempt < self.MAX_RETRIES:
                time.sleep(self.RETRY_DELAY)
        logger.error("Failed to get valid measurement after %d retries", self.MAX_RETRIES)
        return None, None, True

    def close(self):
        if self.bus is not None:
            try:
                self.bus.close()
                logger.info("I2C bus closed")
            except Exception as e:
                logger.error("Error closing I2C bus: %s", e)
            finally:
                self.bus = None

    def __del__(self):
        self.close()


def main():
    dht20 = None
    def signal_handler(sig, frame):
        logger.info("Signal received, shutting down...")
        if dht20:
            dht20.close()
        sys.exit(0)
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)
    try:
        dht20 = DHT20()
        while True:
            temp, hum, crc_err = dht20.get_temperature_and_humidity()
            if crc_err:
                logger.error("Measurement failed due to CRC error")
            else:
                logger.info("Temperature: %.2f C, Humidity: %.2f %%", temp, hum)
            time.sleep(2.0)
    except Exception as e:
        logger.error("Fatal error: %s", e)
    finally:
        if dht20:
            dht20.close()


if __name__ == "__main__":
    main()

