                last_transmission_times[(system_code, unit_code)] = now
                logger.info("Outlet '%s' turned %s", outlet_name, "ON" if state else "OFF")
            else:
                logger.error("Failed to control outlet '%s'.", outlet_name)
        else:
            logger.info("Outlet '%s' already in requested state.", outlet_name)
    except Exception as e:
        logger.error("Error controlling outlet '%s': %s", outlet_name, e)


