import time
import logging
import signal
import sys
from smbus2 import SMBus

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')
logger = logging.getLogger(__name__)

DHT20_I2C_ADDRESS = 0x38
DHT20_MEASURE_REGISTER = 0xAC
DHT20_STATUS_REGISTER = 0x71
MEASUREMENT_COMMAND = [0x33, 0x00]
MEASUREMENT_TIMEOUT = 0.1
MEASUREMENT_POLL_INTERVAL = 0.01
CRC_POLYNOMIAL = 0x31
CRC_INITIAL_VALUE = 0xFF


class DHT20:
    def __init__(self, i2c_bus_number=1, address=DHT20_I2C_ADDRESS):
        self.address = address
        self.bus = None
        self._running = True
        signal.signal(signal.SIGINT, self._signal_handler)
        signal.signal(signal.SIGTERM, self._signal_handler)
        try:
            self.bus = SMBus(i2c_bus_number)
            logger.info(f"Opened I2C bus {i2c_bus_number}")
        except Exception as e:
            logger.error(f"Failed to open I2C bus {i2c_bus_number}: {e}")
            self.bus = None

    def _signal_handler(self, signum, frame):
        logger.info(f"Received signal {signum}, shutting down...")
        self._running = False

    def _crc8(self, data):
        crc = CRC_INITIAL_VALUE
        for byte in data:
            crc ^= byte
            for _ in range(8):
                if crc & 0x80:
                    crc = ((crc << 1) ^ CRC_POLYNOMIAL) & 0xFF
                else:
                    crc = (crc << 1) & 0xFF
        return crc

    def _read_status(self):
        if self.bus is None:
            return None
        try:
            return self.bus.read_byte_data(self.address, DHT20_STATUS_REGISTER)
        except Exception as e:
            logger.error(f"I2C read error from status register: {e}")
            return None

    def _write_register(self, register, data):
        if self.bus is None:
            return False
        try:
            self.bus.write_i2c_block_data(self.address, register, data)
            return True
        except Exception as e:
            logger.error(f"I2C write error to register 0x{register:02X}: {e}")
            return False

    def _read_register(self, register, length):
        if self.bus is None:
            return None
        try:
            return self.bus.read_i2c_block_data(self.address, register, length)
        except Exception as e:
            logger.error(f"I2C read error from register 0x{register:02X}: {e}")
            return None

    def measure(self):
        if self.bus is None:
            logger.error("I2C bus not initialized")
            return None, None, True

        if not self._write_register(DHT20_MEASURE_REGISTER, MEASUREMENT_COMMAND):
            return None, None, True

        start_time = time.time()
        while self._running:
            status = self._read_status()
            if status is None:
                return None, None, True
            if (status & 0x80) == 0:
                break
            if time.time() - start_time > MEASUREMENT_TIMEOUT:
                logger.error("Measurement timeout waiting for sensor to complete")
                return None, None, True
            time.sleep(MEASUREMENT_POLL_INTERVAL)

        data = self._read_register(DHT20_STATUS_REGISTER, 7)
        if data is None or len(data) < 7:
            logger.error("Failed to read measurement data")
            return None, None, True

        calculated_crc = self._crc8(data[:6])
        received_crc = data[6]
        crc_error = calculated_crc != received_crc

        if crc_error:
            logger.warning(f"CRC error: calculated=0x{calculated_crc:02X}, received=0x{received_crc:02X}")

        humidity_raw = ((data[1] << 12) | (data[2] << 4) | (data[3] >> 4)) & 0xFFFFF
        temperature_raw = (((data[3] & 0x0F) << 16) | (data[4] << 8) | data[5]) & 0xFFFFF

        temperature = float(temperature_raw) / 5242.88 - 50.0
        humidity = float(humidity_raw) / 0x100000 * 100.0

        return temperature, humidity, crc_error

    def close(self):
        if self.bus is not None:
            try:
                self.bus.close()
                logger.info("I2C bus closed")
            except Exception as e:
                logger.error(f"Error closing I2C bus: {e}")
            finally:
                self.bus = None


if __name__ == "__main__":
    sensor = DHT20(i2c_bus_number=1, address=DHT20_I2C_ADDRESS)
    try:
        temperature, humidity, crc_error = sensor.measure()
        if temperature is not None and humidity is not None:
            print(f"Temperature: {temperature:.2f} C, Humidity: {humidity:.2f} %")
        else:
            print("Measurement failed")
    except Exception as e:
        logger.error(f"Unexpected error: {e}")
    finally:
        sensor.close()

