import time
import board
import busio
import adafruit_tca9548a
import adafruit_bme280
import adafruit_tsl2591

# Constants
I2C_ADDRESS = 0x70
BME280_CHANNEL = 0
TSL2591_CHANNEL = 1
READ_INTERVAL = 2

# Global resources for cleanup
i2c_bus = None
tca = None
bme280 = None
tsl2591 = None


def initialize_i2c():
    """Initializes the I2C bus."""
    global i2c_bus
    try:
        i2c_bus = busio.I2C(board.SCL, board.SDA)
        return True
    except Exception as e:
        print(f"Error initializing I2C bus: {e}")
        return False


def initialize_multiplexer():
    """Initializes the TCA9548A multiplexer."""
    global tca
    if i2c_bus is None:
        print("I2C bus not initialized.")
        return False
    try:
        tca = adafruit_tca9548a.TCA9548A(i2c_bus, address=I2C_ADDRESS)
        return True
    except ValueError as e:
        print(f"Multiplexer not found at address 0x{I2C_ADDRESS:02X}: {e}")
        return False
    except Exception as e:
        print(f"Error initializing multiplexer: {e}")
        return False


def initialize_bme280():
    """Initializes the BME280 sensor."""
    global bme280
    if tca is None:
        print("Multiplexer not initialized.")
        return False
    try:
        bme280 = adafruit_bme280.Adafruit_BME280_I2C(tca[BME280_CHANNEL])
        return True
    except ValueError as e:
        print(f"BME280 not found on channel {BME280_CHANNEL}: {e}")
        return False
    except Exception as e:
        print(f"Error initializing BME280: {e}")
        return False


def initialize_tsl2591():
    """Initializes the TSL2591 sensor."""
    global tsl2591
    if tca is None:
        print("Multiplexer not initialized.")
        return False
    try:
        tsl2591 = adafruit_tsl2591.TSL2591(tca[TSL2591_CHANNEL])
        return True
    except ValueError as e:
        print(f"TSL2591 not found on channel {TSL2591_CHANNEL}: {e}")
        return False
    except Exception as e:
        print(f"Error initializing TSL2591: {e}")
        return False


def read_bme280_data():
    """Reads temperature and humidity from the BME280 sensor."""
    if bme280 is None:
        return None, None
    try:
        temperature = bme280.temperature
        humidity = bme280.humidity
        return temperature, humidity
    except Exception as e:
        print(f"Error reading BME280 data: {e}")
        return None, None


def read_tsl2591_data():
    """Reads light intensity from the TSL2591 sensor."""
    if tsl2591 is None:
        return None
    try:
        lux = tsl2591.lux
        return lux
    except Exception as e:
        print(f"Error reading TSL2591 data: {e}")
        return None


def print_sensor_data(temperature, humidity, light_intensity):
    """Prints the sensor data to the console."""
    if temperature is not None and humidity is not None and light_intensity is not None:
        print(f"Temperature: {temperature:.2f} °C, Humidity: {humidity:.2f} %, Light Intensity: {light_intensity:.2f} lux")
    else:
        print("Failed to read sensor data.")


def cleanup():
    """Releases resources."""
    global i2c_bus
    if i2c_bus is not None:
        try:
            i2c_bus.deinit()
        except Exception:
            pass
        i2c_bus = None


def main():
    """Main function to read and print sensor data."""
    if not initialize_i2c():
        return
    if not initialize_multiplexer():
        cleanup()
        return
    if not initialize_bme280():
        cleanup()
        return
    if not initialize_tsl2591():
        cleanup()
        return

    try:
        while True:
            temperature, humidity = read_bme280_data()
            light_intensity = read_tsl2591_data()
            print_sensor_data(temperature, humidity, light_intensity)
            time.sleep(READ_INTERVAL)
    except KeyboardInterrupt:
        print("\nExiting program.")
    finally:
        cleanup()


if __name__ == "__main__":
    main()

