        print("I2C bus not initialized.")
        return False
    try:
        tca = adafruit_tca9548a.TCA9548A(i2c_bus, address=I2C_ADDRESS)
        return True
    except ValueError as e:
        print(f"Multiplexer not found at address 0x{I2C_ADDRESS:02X}: {e}")
        return False
    except Exception as e:
        print(f"Error initializing multiplexer: {e}")
        return False


def initialize_bme280():
    """Initializes the BME280 sensor."""
    global bme280
    if tca is None:
        print("Multiplexer not initialized.")
        return False
    try:
        bme280 = adafruit_bme280.Adafruit_BME280_I2C(tca[BME280_CHANNEL])
        return True
    except ValueError as e:
        print(f"BME280 not found on channel {BME280_CHANNEL}: {e}")
        return False
    except Exception as e:
        print(f"Error initializing BME280: {e}")
        return False


def initialize_tsl2591():
