    """Reads temperature and humidity from the BME280 sensor."""
    if bme280 is None:
        return None, None
    try:
        temperature = bme280.temperature
        humidity = bme280.humidity
        return temperature, humidity
    except Exception as e:
        print(f"Error reading BME280 data: {e}")
        return None, None


def read_tsl2591_data():
    """Reads light intensity from the TSL2591 sensor."""
    if tsl2591 is None:
        return None
    try:
        lux = tsl2591.lux
        return lux
    except Exception as e:
        print(f"Error reading TSL2591 data: {e}")
        return None


def print_sensor_data(temperature, humidity, light_intensity):
    """Prints the sensor data to the console."""
    if temperature is not None and humidity is not None and light_intensity is not None:
        print(f"Temperature: {temperature:.2f} °C, Humidity: {humidity:.2f} %, Light Intensity: {light_intensity:.2f} lux")
    else:
        print("Failed to read sensor data.")


def cleanup():
    """Releases resources."""
    global i2c_bus
    if i2c_bus is not None:
        try:
            i2c_bus.deinit()
        except Exception:
            pass
        i2c_bus = None


def main():
    """Main function to read and print sensor data."""
    if not initialize_i2c():
        return
    if not initialize_multiplexer():
        cleanup()
        return
    if not initialize_bme280():
        cleanup()
        return
    if not initialize_tsl2591():
        cleanup()
        return

    try:
        while True:
            temperature, humidity = read_bme280_data()
            light_intensity = read_tsl2591_data()
            print_sensor_data(temperature, humidity, light_intensity)
            time.sleep(READ_INTERVAL)
    except KeyboardInterrupt:
        print("\nExiting program.")
    finally:
        cleanup()


if __name__ == "__main__":
    main()

