import serial
import time
import sys
import os

SERIAL_PORT = '/dev/ttyACM0'
BAUD_RATE = 115200
TIMEOUT = 1.0
LOG_FILE = 'temperature_log.csv'

def open_serial_port():
    try:
        ser = serial.Serial(
            port=SERIAL_PORT,
            baudrate=BAUD_RATE,
            bytesize=serial.EIGHTBITS,
            parity=serial.PARITY_NONE,
            stopbits=serial.STOPBITS_ONE,
            timeout=TIMEOUT
        )
        print(f"Opened {SERIAL_PORT} @ {BAUD_RATE} baud.")
        return ser
    except serial.SerialException as e:
        print(f"Error opening serial port {SERIAL_PORT}: {e}", file=sys.stderr)
        return None

def ensure_log_header(path):
    if not os.path.exists(path):
        try:
            with open(path, 'w', newline='') as f:
                f.write("timestamp,celsius,fahrenheit\n")
        except OSError as e:
            print(f"Error writing log header to {path}: {e}", file=sys.stderr)
            return False
    return True

def log_temperature(ser, log_path):
    while True:
        try:
            raw = ser.readline()
        except serial.SerialException as e:
            print(f"Serial read error: {e}", file=sys.stderr)
            return False

        if not raw:
            continue

        line = raw.decode('ascii', errors='replace').strip()
        if not line:
            continue

        try:
            celsius = float(line)
        except ValueError:
            print(f"Warning: non-numeric data received: {line!r}", file=sys.stderr)
            continue

        fahrenheit = celsius * 9.0 / 5.0 + 32.0
        timestamp = time.strftime('%Y-%m-%d %H:%M:%S')

        try:
            with open(log_path, 'a', newline='') as f:
                f.write(f"{timestamp},{celsius:.2f},{fahrenheit:.2f}\n")
        except OSError as e:
            print(f"Error writing to log file {log_path}: {e}", file=sys.stderr)
            return False

        print(f"{timestamp}  Celsius: {celsius:.2f}  Fahrenheit: {fahrenheit:.2f}")

    return True

def main():
    ser = open_serial_port()
    if ser is None:
        sys.exit(1)

    if not ensure_log_header(LOG_FILE):
        ser.close()
        sys.exit(1)

    try:
        log_temperature(ser, LOG_FILE)
    except KeyboardInterrupt:
        print("\nInterrupted by user.")
    finally:
        ser.close()
        print("Serial port closed.")

if __name__ == '__main__':
    main()

