import time
import signal
import sys
import config
import paho.mqtt.client as mqtt
import adafruit_dht
import board

DEGREE_CELSIUS = "\u00B0C"

running = True
mqtt_client = None
dht_device = None

def signal_handler(signum, frame):
    global running
    running = False

def on_connect(client, userdata, flags, reason_code, properties):
    if reason_code == 0:
        print("Connected to MQTT broker.")
        publish_homie_discovery()
    else:
        print(f"MQTT connection failed with reason code: {reason_code}")

def on_disconnect(client, userdata, flags, reason_code, properties):
    print(f"Disconnected from MQTT broker (reason code: {reason_code}).")

def publish_homie_discovery():
    global mqtt_client
    if mqtt_client is None:
        return
    mqtt_client.publish(f"homie/{config.homieclientid}/$state", "init")
    mqtt_client.publish(f"homie/{config.homieclientid}/$homie", "4.0")
    mqtt_client.publish(f"homie/{config.homieclientid}/$name", config.homieclientname)
    mqtt_client.publish(f"homie/{config.homieclientid}/$nodes", config.homienodes)
    mqtt_client.publish(f"homie/{config.homieclientid}/{config.homienodes}/$name", "DHT22 Sensor")
    mqtt_client.publish(f"homie/{config.homieclientid}/{config.homienodes}/$properties", "temperature,humidity")
    mqtt_client.publish(f"homie/{config.homieclientid}/{config.homienodes}/temperature/$name", "Temperature")
    mqtt_client.publish(f"homie/{config.homieclientid}/{config.homienodes}/temperature/$unit", DEGREE_CELSIUS)
    mqtt_client.publish(f"homie/{config.homieclientid}/{config.homienodes}/temperature/$datatype", "float")
    mqtt_client.publish(f"homie/{config.homieclientid}/{config.homienodes}/temperature/$settable", "false")
    mqtt_client.publish(f"homie/{config.homieclientid}/{config.homienodes}/humidity/$name", "Humidity")
    mqtt_client.publish(f"homie/{config.homieclientid}/{config.homienodes}/humidity/$unit", "%")
    mqtt_client.publish(f"homie/{config.homieclientid}/{config.homienodes}/humidity/$datatype", "float")
    mqtt_client.publish(f"homie/{config.homieclientid}/{config.homienodes}/humidity/$settable", "false")
    mqtt_client.publish(f"homie/{config.homieclientid}/$state", "ready")

def read_dht22_sensor():
    global dht_device
    if dht_device is None:
        return None, None
    for attempt in range(3):
        try:
            temperature = dht_device.temperature
            humidity = dht_device.humidity
            if temperature is not None and humidity is not None:
                return temperature, humidity
        except RuntimeError as e:
            print(f"DHT22 read error (attempt {attempt + 1}/3): {e}")
        except Exception as e:
            print(f"Unexpected DHT22 error (attempt {attempt + 1}/3): {e}")
        time.sleep(2)
    return None, None

def publish_sensor_data(temperature, humidity):
    global mqtt_client
    if mqtt_client is None:
        return
    if temperature is not None and humidity is not None:
        mqtt_client.publish(f"homie/{config.homieclientid}/{config.homienodes}/temperature", f"{temperature:.1f}")
        mqtt_client.publish(f"homie/{config.homieclientid}/{config.homienodes}/humidity", f"{humidity:.1f}")
    else:
        print("Failed to read sensor data after retries.")

def cleanup():
    global mqtt_client, dht_device
    print("Cleaning up resources...")
    if mqtt_client is not None:
        try:
            mqtt_client.publish(f"homie/{config.homieclientid}/$state", "lost")
            mqtt_client.loop_stop()
            mqtt_client.disconnect()
        except Exception:
            pass
    if dht_device is not None:
        try:
            dht_device.exit()
        except Exception:
            pass
    print("Cleanup complete.")

def main():
    global mqtt_client, dht_device
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    try:
        dht_device = adafruit_dht.DHT22(board.D4)
        time.sleep(2)
    except Exception as e:
        print(f"Failed to initialize DHT22 sensor: {e}")
        sys.exit(1)

    try:
        mqtt_client = mqtt.Client(
            callback_api_version=mqtt.CallbackAPIVersion.VERSION2,
            client_id=config.mqttclientid
        )
        if config.mqttusername and config.mqttpassword:
            mqtt_client.username_pw_set(config.mqttusername, config.mqttpassword)
        mqtt_client.on_connect = on_connect
        mqtt_client.on_disconnect = on_disconnect
        mqtt_client.connect(config.mqttbroker, config.mqttport, keepalive=60)
        mqtt_client.loop_start()
    except Exception as e:
        print(f"Failed to connect to MQTT broker: {e}")
        cleanup()
        sys.exit(1)

    try:
        while running:
            temperature, humidity = read_dht22_sensor()
            publish_sensor_data(temperature, humidity)
            for _ in range(config.publishtime):
                if not running:
                    break
                time.sleep(1)
    except Exception as e:
        print(f"Unexpected error in main loop: {e}")
    finally:
        cleanup()

if __name__ == "__main__":
    main()

