import time
import signal
import sys
import logging
from gpiozero import PWMOutputDevice

logging.basicConfig(
    level=logging.INFO,
    format="%(asctime)s [%(levelname)s] %(message)s",
)
logger = logging.getLogger(__name__)

FAN_PIN = 14
PWM_FREQ = 100
CHECK_INTERVAL = 5

TEMP_THRESHOLDS = [
    (70.0, 100.0),
    (60.0, 85.0),
    (50.0, 70.0),
    (40.0, 50.0),
    (32.0, 25.0),
    (25.0, 15.0),
]


class FanController:
    def __init__(self, pin: int, freq: int):
        self.pin = pin
        self.freq = freq
        self.fan = None
        self._running = True

    def _read_cpu_temp(self) -> float | None:
        try:
            with open("/sys/class/thermal/thermal_zone0/temp", "r") as f:
                raw = f.read().strip()
            return float(raw) / 1000.0
        except (OSError, ValueError) as e:
            logger.warning("Failed to read CPU temperature: %s", e)
            return None

    def _get_target_speed(self, temp: float) -> float:
        for threshold, speed in TEMP_THRESHOLDS:
            if temp > threshold:
                return speed
        return 0.0

    def _signal_handler(self, signum, frame):
        logger.info("Signal %s received, shutting down...", signum)
        self._running = False

    def run(self):
        signal.signal(signal.SIGTERM, self._signal_handler)
        signal.signal(signal.SIGINT, self._signal_handler)

        try:
            self.fan = PWMOutputDevice(self.pin, frequency=self.freq, initial_value=0.0)
        except Exception as e:
            logger.error("Failed to initialize PWM on GPIO%d: %s", self.pin, e)
            return

        logger.info("Fan control started on GPIO%d @ %d Hz", self.pin, self.freq)

        try:
            while self._running:
                temp = self._read_cpu_temp()
                if temp is None:
                    logger.warning("Skipping cycle due to temperature read failure")
                else:
                    speed = self._get_target_speed(temp)
                    self.fan.value = speed / 100.0
                    logger.info("CPU: %.1f°C  Fan: %.0f%%", temp, speed)

                for _ in range(CHECK_INTERVAL):
                    if not self._running:
                        break
                    time.sleep(1)
        finally:
            self.cleanup()

    def cleanup(self):
        if self.fan is not None:
            try:
                self.fan.value = 0.0
                self.fan.close()
            except Exception as e:
                logger.error("Error during fan cleanup: %s", e)
            finally:
                self.fan = None
        logger.info("Fan control stopped")


if __name__ == "__main__":
    controller = FanController(FAN_PIN, PWM_FREQ)
    controller.run()

