import config
import time
import signal
import sys
import logging

import paho.mqtt.client as mqtt
import paho.mqtt.enums as mqtt_enums

try:
    import board
    import adafruit_dht
except ImportError:
    logging.error("Missing dependencies. Install with: pip install adafruit-circuitpython-dht paho-mqtt")
    sys.exit(1)

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')
logger = logging.getLogger(__name__)

DEGREE_CELSIUS = "\u00B0C"

running = True
dht_device = None
mqtt_client = None


def signal_handler(signum, frame):
    global running
    logger.info(f"Signal {signum} received, shutting down...")
    running = False


def on_connect(client, userdata, flags, reason_code, properties):
    if reason_code == 0:
        logger.info("Connected to MQTT broker successfully")
    else:
        logger.error(f"Failed to connect to MQTT broker, reason code: {reason_code}")


def on_disconnect(client, userdata, flags, reason_code, properties):
    if reason_code != 0:
        logger.warning(f"Unexpected MQTT disconnect, reason code: {reason_code}")
    else:
        logger.info("Disconnected from MQTT broker")


def publish_sensor_data(client, temperature, humidity):
    try:
        temp_topic = f"homie/{config.homieclientid}/{config.homienodes}/temperature"
        hum_topic = f"homie/{config.homieclientid}/{config.homienodes}/humidity"

        client.publish(temp_topic, f"{temperature:.1f}", qos=1)
        client.publish(hum_topic, f"{humidity:.1f}", qos=1)
        logger.info(f"Published - Temp: {temperature:.1f}{DEGREE_CELSIUS}, Humidity: {humidity:.1f}%")
    except Exception as e:
        logger.error(f"Error publishing data: {e}")


def read_dht22_data():
    global dht_device
    if dht_device is None:
        try:
            pin_map = {
                4: board.D4,
                17: board.D17,
                18: board.D18,
                22: board.D22,
                23: board.D23,
                24: board.D24,
                25: board.D25,
                27: board.D27,
            }
            pin = pin_map.get(config.dhtgpiopin)
            if pin is None:
                raise ValueError(f"Unsupported GPIO pin: {config.dhtgpiopin}")
            dht_device = adafruit_dht.DHT22(pin, use_pulseio=False)
            logger.info(f"DHT22 initialized on GPIO {config.dhtgpiopin}")
        except Exception as e:
            logger.error(f"Failed to initialize DHT22: {e}")
            return None, None

    try:
        temperature = dht_device.temperature
        humidity = dht_device.humidity
        if temperature is None or humidity is None:
            raise RuntimeError("DHT22 returned None for temperature or humidity")
        return temperature, humidity
    except RuntimeError as e:
        logger.warning(f"DHT22 read error (retrying in 2s): {e}")
        return None, None
    except Exception as e:
        logger.error(f"Unexpected DHT22 error: {e}")
        return None, None


def main():
    global mqtt_client, running

    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    try:
        mqtt_client = mqtt.Client(
            mqtt.CallbackAPIVersion.VERSION2,
            client_id=config.mqttclientid,
            clean_session=True,
        )
        mqtt_client.username_pw_set(config.mqttusername, config.mqttpassword)
        mqtt_client.on_connect = on_connect
        mqtt_client.on_disconnect = on_disconnect

        mqtt_client.connect(config.mqttbroker, port=config.mqttport, keepalive=60)
        mqtt_client.loop_start()

        while running:
            temperature, humidity = read_dht22_data()
            if temperature is not None and humidity is not None:
                publish_sensor_data(mqtt_client, temperature, humidity)
            else:
                logger.warning("Skipping publish due to DHT22 read failure")

            for _ in range(config.publishtime):
                if not running:
                    break
                time.sleep(1)

    except Exception as e:
        logger.error(f"An unexpected error occurred: {e}")
    finally:
        if mqtt_client is not None:
            try:
                mqtt_client.loop_stop()
                mqtt_client.disconnect()
                logger.info("MQTT client disconnected")
            except Exception as e:
                logger.error(f"Error disconnecting MQTT client: {e}")
        if dht_device is not None:
            try:
                dht_device.exit()
                logger.info("DHT22 sensor released")
            except Exception as e:
                logger.error(f"Error releasing DHT22 sensor: {e}")
        logger.info("Cleanup complete. Exiting.")


if __name__ == "__main__":
    main()

