            clean_session=True,
        )
        mqtt_client.username_pw_set(config.mqttusername, config.mqttpassword)
        mqtt_client.on_connect = on_connect
        mqtt_client.on_disconnect = on_disconnect

        mqtt_client.connect(config.mqttbroker, port=config.mqttport, keepalive=60)
        mqtt_client.loop_start()

        while running:
            temperature, humidity = read_dht22_data()
            if temperature is not None and humidity is not None:
                publish_sensor_data(mqtt_client, temperature, humidity)
            else:
                logger.warning("Skipping publish due to DHT22 read failure")

            for _ in range(config.publishtime):
                if not running:
                    break
                time.sleep(1)

    except Exception as e:
        logger.error(f"An unexpected error occurred: {e}")
    finally:
        if mqtt_client is not None:
            try:
                mqtt_client.loop_stop()
                mqtt_client.disconnect()
                logger.info("MQTT client disconnected")
            except Exception as e:
                logger.error(f"Error disconnecting MQTT client: {e}")
        if dht_device is not None:
            try:
                dht_device.exit()
                logger.info("DHT22 sensor released")
            except Exception as e:
                logger.error(f"Error releasing DHT22 sensor: {e}")
        logger.info("Cleanup complete. Exiting.")


if __name__ == "__main__":
    main()

