import signal
import sys
import time
import logging
from ina219 import INA219, DeviceRangeError
from smbus2 import SMBus, i2c_msg

# Configure logging
logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

# Constants
DEVICE_BUS = 1
DEVICE_ADDRESS = 0x17
SUPPLY_INA219_ADDRESS = 0x40
BATTERY_INA219_ADDRESS = 0x45
SHUNT_RESISTOR_SUPPLY = 0.00725
SHUNT_RESISTOR_BATTERY = 0.005

# Global flag for graceful shutdown
running = True

def signal_handler(sig, frame):
    global running
    logging.info("Shutdown signal received. Cleaning up...")
    running = False

class INA219Sensor:
    """
    A class to handle INA219 sensor readings and error handling.
    """
    def __init__(self, address, shunt_resistor, bus_num=DEVICE_BUS):
        self.address = address
        self.shunt_resistor = shunt_resistor
        self.bus_num = bus_num
        self.ina219 = None
        self.initialize()

    def initialize(self):
        try:
            self.ina219 = INA219(self.shunt_resistor, busnum=self.bus_num, address=self.address)
            self.ina219.configure()
            logging.info(f"INA219 sensor at address 0x{self.address:02X} initialized successfully.")
        except Exception as e:
            logging.error(f"Failed to initialize INA219 sensor at address 0x{self.address:02X}: {e}")
            self.ina219 = None

    def read_voltage(self):
        if self.ina219 is None:
            logging.error(f"INA219 sensor at address 0x{self.address:02X} not initialized.")
            return None
        try:
            return self.ina219.voltage()
        except DeviceRangeError:
            logging.warning(f"Current out of range for INA219 sensor at address 0x{self.address:02X}.")
            return None
        except Exception as e:
            logging.error(f"Error reading voltage from INA219 sensor at address 0x{self.address:02X}: {e}")
            return None

    def read_current(self):
        if self.ina219 is None:
            logging.error(f"INA219 sensor at address 0x{self.address:02X} not initialized.")
            return None
        try:
            return self.ina219.current()
        except DeviceRangeError:
            logging.warning(f"Current out of range for INA219 sensor at address 0x{self.address:02X}.")
            return None
        except Exception as e:
            logging.error(f"Error reading current from INA219 sensor at address 0x{self.address:02X}: {e}")
            return None

    def read_power(self):
        if self.ina219 is None:
            logging.error(f"INA219 sensor at address 0x{self.address:02X} not initialized.")
            return None
        try:
            return self.ina219.power()
        except DeviceRangeError:
            logging.warning(f"Current out of range for INA219 sensor at address 0x{self.address:02X}.")
            return None
        except Exception as e:
            logging.error(f"Error reading power from INA219 sensor at address 0x{self.address:02X}: {e}")
            return None

    def close(self):
        if self.ina219 is not None:
            try:
                self.ina219.close()
                logging.info(f"INA219 sensor at address 0x{self.address:02X} closed.")
            except Exception as e:
                logging.error(f"Error closing INA219 sensor at address 0x{self.address:02X}: {e}")
            finally:
                self.ina219 = None

class UPSPlus:
    """
    A class to handle the UPS Plus HAT functionalities.
    """
    def __init__(self, bus_num=DEVICE_BUS, address=DEVICE_ADDRESS):
        self.bus_num = bus_num
        self.address = address
        self.bus = None
        self.supply_sensor = INA219Sensor(SUPPLY_INA219_ADDRESS, SHUNT_RESISTOR_SUPPLY, bus_num)
        self.battery_sensor = INA219Sensor(BATTERY_INA219_ADDRESS, SHUNT_RESISTOR_BATTERY, bus_num)
        self.initialize_i2c()

    def initialize_i2c(self):
        try:
            self.bus = SMBus(self.bus_num)
            logging.info(f"I2C bus {self.bus_num} initialized successfully.")
        except Exception as e:
            logging.error(f"Failed to initialize I2C bus {self.bus_num}: {e}")
            self.bus = None

    def read_register(self, register):
        if self.bus is None:
            logging.error("I2C bus not initialized.")
            return None
        try:
            write_msg = i2c_msg.write(self.address, [register])
            read_msg = i2c_msg.read(self.address, 1)
            self.bus.i2c_rdwr(write_msg, read_msg)
            return list(read_msg)[0]
        except Exception as e:
            logging.error(f"Error reading register 0x{register:02X} from UPS Plus: {e}")
            return None

    def read_block_data(self, register, length):
        if self.bus is None:
            logging.error("I2C bus not initialized.")
            return None
        try:
            write_msg = i2c_msg.write(self.address, [register])
            read_msg = i2c_msg.read(self.address, length)
            self.bus.i2c_rdwr(write_msg, read_msg)
            return list(read_msg)
        except Exception as e:
            logging.error(f"Error reading block data from register 0x{register:02X} from UPS Plus: {e}")
            return None

    def read_all_registers(self):
        if self.bus is None:
            logging.error("I2C bus not initialized.")
            return None
        try:
            write_msg = i2c_msg.write(self.address, [0x00])
            read_msg = i2c_msg.read(self.address, 256)
            self.bus.i2c_rdwr(write_msg, read_msg)
            return list(read_msg)
        except Exception as e:
            logging.error(f"Error reading all registers from UPS Plus: {e}")
            return None

    def get_all_data(self):
        data = self.read_all_registers()
        if data is None:
            return None

        def get_u16(idx):
            return (data[idx] << 8) | data[idx + 1]

        def get_s16(idx):
            val = get_u16(idx)
            if val >= 0x8000:
                val -= 0x10000
            return val

        def get_u32(idx):
            return (data[idx] << 24) | (data[idx + 1] << 16) | (data[idx + 2] << 8) | data[idx + 3]

        def get_s32(idx):
            val = get_u32(idx)
            if val >= 0x80000000:
                val -= 0x100000000
            return val

        return {
            'processor_voltage': get_u16(0x01),
            'raspberry_pi_voltage': get_u16(0x03),
            'battery_port_voltage': get_u16(0x05),
            'type_c_charging_port_voltage': get_u16(0x07),
            'micro_usb_charging_port_voltage': get_u16(0x09),
            'battery_temperature': get_s16(0x0B),
            'full_battery_voltage': get_u16(0x0D),
            'empty_battery_voltage': get_u16(0x0F),
            'battery_protection_voltage': get_u16(0x11),
            'remaining_capacity_percent': get_u16(0x13),
            'sampling_period_minutes': get_u16(0x15),
            'power_state': data[0x17],
            'shutdown_countdown_seconds': get_u16(0x18),
            'auto_power_on': data[0x19],
            'restart_countdown_seconds': get_u16(0x1A),
        }

    def print_all_data(self):
        data = self.get_all_data()
        if data is None:
            logging.error("Failed to get all data from UPS Plus.")
            return

        print("=" * 50)
        print("UPS Plus HAT Data")
        print("=" * 50)
        print(f"Processor Voltage: {data['processor_voltage']} mV")
        print(f"Raspberry Pi Voltage: {data['raspberry_pi_voltage']} mV")
        print(f"Battery Port Voltage: {data['battery_port_voltage']} mV")
        print(f"Type-C Charging Port Voltage: {data['type_c_charging_port_voltage']} mV")
        print(f"Micro-USB Charging Port Voltage: {data['micro_usb_charging_port_voltage']} mV")
        print(f"Battery Temperature: {data['battery_temperature']} °C")
        print(f"Full Battery Voltage: {data['full_battery_voltage']} mV")
        print(f"Empty Battery Voltage: {data['empty_battery_voltage']} mV")
        print(f"Battery Protection Voltage: {data['battery_protection_voltage']} mV")
        print(f"Remaining Capacity: {data['remaining_capacity_percent']} %")
        print(f"Sampling Period: {data['sampling_period_minutes']} minutes")
        print(f"Power State: {data['power_state']}")
        print(f"Shutdown Countdown: {data['shutdown_countdown_seconds']} seconds")
        print(f"Auto Power On: {data['auto_power_on']}")
        print(f"Restart Countdown: {data['restart_countdown_seconds']} seconds")
        print("=" * 50)

    def close(self):
        if self.bus is not None:
            try:
                self.bus.close()
                logging.info("I2C bus closed.")
            except Exception as e:
                logging.error(f"Error closing I2C bus: {e}")
            finally:
                self.bus = None
        self.supply_sensor.close()
        self.battery_sensor.close()

def main():
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    ups = UPSPlus()

    try:
        while running:
            print("=" * 50)
            print("Current System Status")
            print("=" * 50)

            supply_voltage = ups.supply_sensor.read_voltage()
            supply_current = ups.supply_sensor.read_current()
            supply_power = ups.supply_sensor.read_power()

            if supply_voltage is not None:
                print(f"Supply Voltage: {supply_voltage:.3f} V")
            else:
                print("Supply Voltage: Error reading")

            if supply_current is not None:
                print(f"Supply Current: {supply_current:.3f} mA")
            else:
                print("Supply Current: Error reading")

            if supply_power is not None:
                print(f"Supply Power: {supply_power:.3f} mW")
            else:
                print("Supply Power: Error reading")

            battery_voltage = ups.battery_sensor.read_voltage()
            battery_current = ups.battery_sensor.read_current()
            battery_power = ups.battery_sensor.read_power()

            if battery_voltage is not None:
                print(f"Battery Voltage: {battery_voltage:.3f} V")
            else:
                print("Battery Voltage: Error reading")

            if battery_current is not None:
                print(f"Battery Current: {battery_current:.3f} mA")
            else:
                print("Battery Current: Error reading")

            if battery_power is not None:
                print(f"Battery Power: {battery_power:.3f} mW")
            else:
                print("Battery Power: Error reading")

            ups.print_all_data()

            time.sleep(1)

    except Exception as e:
        logging.error(f"An unexpected error occurred: {e}")
    finally:
        ups.close()
        logging.info("Program terminated.")

if __name__ == "__main__":
    main()

