import subprocess
import time
import logging
import signal
import sys

from gpiozero import PWMOutputDevice

logging.basicConfig(
    level=logging.INFO,
    format="%(asctime)s [%(levelname)s] %(message)s",
)
logger = logging.getLogger(__name__)

FAN_PIN = 14
PWM_FREQ = 100
CHECK_INTERVAL = 5

TEMP_THRESHOLDS = [
    (70.0, 100.0),
    (60.0, 85.0),
    (50.0, 70.0),
    (40.0, 50.0),
    (32.0, 25.0),
    (25.0, 15.0),
]

_running = True


def _handle_signal(signum, frame):
    global _running
    logger.info("Received signal %s, shutting down...", signum)
    _running = False


def get_cpu_temperature():
    try:
        result = subprocess.run(
            ["vcgencmd", "measure_temp"],
            capture_output=True,
            text=True,
            timeout=5,
            check=True,
        )
        return float(result.stdout.strip().split("=")[1].split("'")[0])
    except (subprocess.CalledProcessError, subprocess.TimeoutExpired, IndexError, ValueError) as e:
        logger.error("Failed to read CPU temperature: %s", e)
        return None
    except FileNotFoundError:
        logger.error("vcgencmd not found. Is this running on a Raspberry Pi?")
        return None


def calculate_fan_speed(temp):
    if temp is None:
        return None
    for threshold, speed in TEMP_THRESHOLDS:
        if temp > threshold:
            return speed
    return 0.0


def main():
    global _running

    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    fan = None
