import serial
import time
import signal
import sys

SERIAL_PORT = '/dev/ttyUSB0'
BAUD_RATE = 9600
TEMP_THRESHOLD = 30.0
HUMIDITY_THRESHOLD = 70.0
READ_INTERVAL = 1

running = True

def signal_handler(signum, frame):
    global running
    running = False

def read_sensor_data(serial_port):
    try:
        raw = serial_port.readline()
        if not raw:
            return None
        line = raw.decode('ascii', errors='replace').strip()
        if not line:
            return None
        parts = line.split(',')
        if len(parts) != 2:
            return None
        temperature = float(parts[0])
        humidity = float(parts[1])
        return temperature, humidity
    except ValueError:
        return None
    except serial.SerialException:
        return None

def check_thresholds(temperature, humidity):
    if temperature > TEMP_THRESHOLD:
        print(f"ALERT: Temperature {temperature:.1f}°C exceeds threshold {TEMP_THRESHOLD}°C")
    if humidity > HUMIDITY_THRESHOLD:
        print(f"ALERT: Humidity {humidity:.1f}% exceeds threshold {HUMIDITY_THRESHOLD}%")

def main():
    global running
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    serial_connection = None
    try:
        serial_connection = serial.Serial(SERIAL_PORT, BAUD_RATE, timeout=1)
        print(f"Connected to {SERIAL_PORT} at {BAUD_RATE} baud.")

        while running:
            sensor_data = read_sensor_data(serial_connection)
            if sensor_data:
                temperature, humidity = sensor_data
                print(f"Temperature: {temperature:.1f}°C, Humidity: {humidity:.1f}%")
                check_thresholds(temperature, humidity)
            time.sleep(READ_INTERVAL)

    except serial.SerialException as e:
        print(f"Error opening serial port: {e}")
    except Exception as e:
        print(f"Unexpected error: {e}")
    finally:
        if serial_connection and serial_connection.is_open:
            serial_connection.close()
            print("Serial port closed.")

if __name__ == "__main__":
    main()

