import RPi.GPIO as GPIO
import time
import sys

LED_PIN = 17

def setup_gpio():
    """Initialize GPIO17 as an output, starting LOW."""
    try:
        GPIO.setmode(GPIO.BCM)
        GPIO.setup(LED_PIN, GPIO.OUT, initial=GPIO.LOW)
    except Exception as e:
        print(f"GPIO setup failed: {e}")
        sys.exit(1)

def cleanup_gpio():
    """Drive the LED low and release the GPIO pin."""
    try:
        GPIO.output(LED_PIN, GPIO.LOW)
        GPIO.cleanup(LED_PIN)
    except Exception as e:
        print(f"GPIO cleanup warning: {e}")

def main():
    setup_gpio()
    led_state = False
    try:
        while True:
            user_input = input("Enter 'on' or 'off': ").strip().lower()
            if user_input == "on":
                led_state = True
                GPIO.output(LED_PIN, GPIO.HIGH)
            elif user_input == "off":
                led_state = False
                GPIO.output(LED_PIN, GPIO.LOW)
            else:
                print("Invalid input")
            print(f"LED state: {led_state}")
            time.sleep(0.1)
    except KeyboardInterrupt:
        print("\nExiting program.")
    finally:
        cleanup_gpio()

if __name__ == "__main__":
    main()

