import sys
import threading
import time
import signal
import RPi.GPIO as GPIO
import DOG

# Constants
DEFAULT_FILENAME = "data.log"
POLL_INTERVAL = 0.1  # seconds

# Global state
server_state = {
    "is_running": False,
    "filename": DEFAULT_FILENAME,
    "log_file": None,
    "receive_thread": None,
    "gpio_initialized": False
}

# Help messages
help_messages = {
    "help": "Call 'help <command>' to see details.\nCommands:\n\t- start <filename>\n\t- stop\n\t- help\n\t- display\n\t- send <data>\n\t- write <data>\n\t- exit",
    "start": "Starts the server and logs data to the specified file.\nUsage: start <filename>",
    "stop": "Stops the server and cleans up resources.",
    "help": "Displays help information.\nUsage: help [command]",
    "display": "Displays the contents of the log file.\nUsage: display",
    "send": "Sends data using DOG.send().\nUsage: send <data>",
    "write": "Writes data directly to the log file.\nUsage: write <data>",
    "exit": "Exits the server and cleans up resources."
}

def signal_handler(signum, frame):
    """Handle SIGINT and SIGTERM for graceful shutdown."""
    print(f"\nReceived signal {signum}. Shutting down...")
    stop_server()
    GPIO.cleanup()
    sys.exit(0)

def initialize_gpio():
    """Initialize GPIO mode and set up DOG."""
    try:
        GPIO.setmode(GPIO.BCM)
        server_state["gpio_initialized"] = True
        print("GPIO initialized successfully.")
    except Exception as e:
        print(f"Error initializing GPIO: {e}")
        sys.exit(1)

def start_server(filename):
    """Starts the server and creates the log file."""
    if server_state["is_running"]:
        print("Server is already running.")
        return

    try:
        server_state["log_file"] = open(filename, "a")
        server_state["filename"] = filename
        server_state["is_running"] = True
        print(f"Server started. Logging to {filename}")

        # Start the receive thread
        server_state["receive_thread"] = threading.Thread(target=receive_loop, daemon=True)
        server_state["receive_thread"].start()

    except FileNotFoundError:
        print(f"Error: File not found: {filename}")
    except PermissionError:
        print(f"Error: Permission denied: {filename}")
    except Exception as e:
        print(f"Error starting server: {e}")

def stop_server():
    """Stops the server and cleans up resources."""
    if not server_state["is_running"]:
        print("Server is not running.")
        return

    server_state["is_running"] = False
    print("Stopping server...")

    # Wait for the receive thread to finish
    if server_state["receive_thread"] and server_state["receive_thread"].is_alive():
        server_state["receive_thread"].join(timeout=2.0)
        if server_state["receive_thread"].is_alive():
            print("Warning: Receive thread did not stop cleanly.")

    # Close the log file
    if server_state["log_file"]:
        try:
            server_state["log_file"].close()
            print("Log file closed.")
        except Exception as e:
            print(f"Error closing log file: {e}")
        finally:
            server_state["log_file"] = None

    print("Server stopped.")

def receive_loop():
    """Continuously receives data and writes it to the log file."""
    while server_state["is_running"]:
        try:
            data = DOG.receive()
            if data:
                timestamp = time.strftime("%Y-%m-%d %H:%M:%S")
                log_entry = f"{timestamp}: {data}\n"
                server_state["log_file"].write(log_entry)
                server_state["log_file"].flush()
                print(f"Received: {data}")
        except Exception as e:
            print(f"Error receiving data: {e}")
            break
        time.sleep(POLL_INTERVAL)

def send_data(data):
    """Sends data using DOG.send()."""
    if not server_state["is_running"]:
        print("Server must be started first.")
        return
    try:
        DOG.send(data)
        print(f"Sent: {data}")
    except Exception as e:
        print(f"Error sending data: {e}")

def write_to_log(data):
    """Writes data directly to the log file."""
    if not server_state["is_running"]:
        print("Server must be started first.")
        return
    try:
        timestamp = time.strftime("%Y-%m-%d %H:%M:%S")
        log_entry = f"{timestamp}: {data}\n"
        server_state["log_file"].write(log_entry)
        server_state["log_file"].flush()
        print(f"Wrote to log: {data}")
    except Exception as e:
        print(f"Error writing to log: {e}")

def display_log():
    """Displays the contents of the log file."""
    if not server_state["is_running"]:
        print("Server must be started first.")
        return
    try:
        with open(server_state["filename"], "r") as f:
            print(f.read())
    except FileNotFoundError:
        print(f"Error: File not found: {server_state['filename']}")
    except PermissionError:
        print(f"Error: Permission denied: {server_state['filename']}")
    except Exception as e:
        print(f"Error displaying log: {e}")

def run_command(command):
    """Parses and executes a command."""
    parts = command.split()
    if not parts:
        return

    cmd = parts[0].lower()
    args = parts[1:]

    if cmd == "help":
        if args:
            print(help_messages.get(args[0], "No help found for this command."))
        else:
            print(help_messages["help"])
    elif cmd == "start":
        if args:
            start_server(args[0])
        else:
            print("Usage: start <filename>")
    elif cmd == "stop":
        stop_server()
    elif cmd == "display":
        display_log()
    elif cmd == "send":
        if args:
            send_data(" ".join(args))
        else:
            print("Usage: send <data>")
    elif cmd == "write":
        if args:
            write_to_log(" ".join(args))
        else:
            print("Usage: write <data>")
    elif cmd == "exit":
        stop_server()
        GPIO.cleanup()
        sys.exit(0)
    else:
        print(f"Unknown command: {cmd}. Type 'help' for available commands.")

def main():
    """Main function to run the server."""
    # Register signal handlers
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    initialize_gpio()

    print("Raspberry Pi DOG Server")
    print("Type 'help' for available commands.")

    try:
        while True:
            try:
                command = input("> ")
                run_command(command)
            except EOFError:
                print("\nEOF received. Exiting.")
                break
            except Exception as e:
                print(f"An unexpected error occurred: {e}")
    finally:
        stop_server()
        GPIO.cleanup()
        print("GPIO cleaned up. Exiting.")

if __name__ == "__main__":
    main()

