                print(f"Received: {data}")
        except Exception as e:
            print(f"Error receiving data: {e}")
            break
        time.sleep(POLL_INTERVAL)

def send_data(data):
    """Sends data using DOG.send()."""
    if not server_state["is_running"]:
        print("Server must be started first.")
        return
    try:
        DOG.send(data)
        print(f"Sent: {data}")
    except Exception as e:
        print(f"Error sending data: {e}")

def write_to_log(data):
    """Writes data directly to the log file."""
    if not server_state["is_running"]:
        print("Server must be started first.")
        return
    try:
        timestamp = time.strftime("%Y-%m-%d %H:%M:%S")
        log_entry = f"{timestamp}: {data}\n"
        server_state["log_file"].write(log_entry)
        server_state["log_file"].flush()
        print(f"Wrote to log: {data}")
    except Exception as e:
        print(f"Error writing to log: {e}")

def display_log():
    """Displays the contents of the log file."""
    if not server_state["is_running"]:
        print("Server must be started first.")
        return
    try:
        with open(server_state["filename"], "r") as f:
            print(f.read())
    except FileNotFoundError:
        print(f"Error: File not found: {server_state['filename']}")
    except PermissionError:
        print(f"Error: Permission denied: {server_state['filename']}")
    except Exception as e:
        print(f"Error displaying log: {e}")

def run_command(command):
    """Parses and executes a command."""
    parts = command.split()
    if not parts:
        return

    cmd = parts[0].lower()
    args = parts[1:]

    if cmd == "help":
        if args:
            print(help_messages.get(args[0], "No help found for this command."))
        else:
            print(help_messages["help"])
    elif cmd == "start":
        if args:
            start_server(args[0])
        else:
            print("Usage: start <filename>")
    elif cmd == "stop":
        stop_server()
    elif cmd == "display":
        display_log()
    elif cmd == "send":
        if args:
            send_data(" ".join(args))
        else:
            print("Usage: send <data>")
    elif cmd == "write":
        if args:
            write_to_log(" ".join(args))
        else:
            print("Usage: write <data>")
    elif cmd == "exit":
        stop_server()
        GPIO.cleanup()
        sys.exit(0)
    else:
        print(f"Unknown command: {cmd}. Type 'help' for available commands.")

def main():
    """Main function to run the server."""
    # Register signal handlers
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    initialize_gpio()

    print("Raspberry Pi DOG Server")
    print("Type 'help' for available commands.")

    try:
        while True:
            try:
                command = input("> ")
                run_command(command)
            except EOFError:
                print("\nEOF received. Exiting.")
                break
            except Exception as e:
                print(f"An unexpected error occurred: {e}")
    finally:
        stop_server()
        GPIO.cleanup()
        print("GPIO cleaned up. Exiting.")

if __name__ == "__main__":
    main()

