import time
import signal
import sys
import board
import busio
import adafruit_tsl2561
import RPi.GPIO as GPIO

# Constants
PWM_PIN = 18
PWM_FREQUENCY = 1000
LUX_MIN = 0.0
LUX_MAX = 1000.0
UPDATE_INTERVAL = 1.0

# Global resources for cleanup
_pwm = None
_i2c = None
_running = True


def _signal_handler(signum, frame):
    """Handle SIGINT/SIGTERM for graceful shutdown."""
    global _running
    _running = False


def initialize_i2c():
    """Initialize the I2C bus on busio.I2C(board.SCL, board.SDA)."""
    try:
        return busio.I2C(board.SCL, board.SDA)
    except Exception as e:
        print(f"Error initializing I2C bus: {e}", file=sys.stderr)
        return None


def initialize_light_sensor(i2c_bus):
    """Initialize the TSL2561 sensor with auto-gain and 402 ms integration time."""
    try:
        sensor = adafruit_tsl2561.TSL2561(i2c_bus)
        sensor.gain = adafruit_tsl2561.GAIN_AUTO
        sensor.integration_time = adafruit_tsl2561.INTEGRATIONTIME_402MS
        return sensor
    except ValueError as e:
        print(f"TSL2561 not found at default address 0x39: {e}", file=sys.stderr)
        return None
    except Exception as e:
        print(f"Error initializing TSL2561 sensor: {e}", file=sys.stderr)
        return None


def initialize_gpio():
    """Initialize GPIO for PWM output."""
    try:
        GPIO.setmode(GPIO.BCM)
        GPIO.setup(PWM_PIN, GPIO.OUT)
        pwm = GPIO.PWM(PWM_PIN, PWM_FREQUENCY)
        pwm.start(0)
        return pwm
    except Exception as e:
        print(f"Error initializing GPIO/PWM: {e}", file=sys.stderr)
        return None


def read_light_level(sensor):
    """Read lux from the TSL2561 sensor, returning None on error."""
    try:
        return sensor.lux
    except OSError as e:
        print(f"I2C read error: {e}", file=sys.stderr)
        return None
    except Exception as e:
        print(f"Unexpected error reading light level: {e}", file=sys.stderr)
        return None


def calculate_brightness(lux):
    """Map lux to a 0-100 brightness percentage, clamped."""
    if lux is None:
        return 0.0
    clamped = max(LUX_MIN, min(lux, LUX_MAX))
    return (clamped - LUX_MIN) / (LUX_MAX - LUX_MIN) * 100.0


def cleanup():
    """Release all resources safely."""
    global _pwm, _i2c
    if _pwm is not None:
        try:
            _pwm.stop()
        except Exception:
            pass
        _pwm = None
    if _i2c is not None:
        try:
            _i2c.deinit()
        except Exception:
            pass
        _i2c = None
    try:
        GPIO.cleanup()
    except Exception:
        pass


def main():
    """Main loop: read light, update PWM, print status every second."""
    global _pwm, _i2c

    # Register signal handlers for graceful shutdown
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    # Initialize I2C
    _i2c = initialize_i2c()
    if _i2c is None:
        cleanup()
        sys.exit(1)

    # Initialize light sensor
    light_sensor = initialize_light_sensor(_i2c)
    if light_sensor is None:
        cleanup()
        sys.exit(1)

    # Initialize GPIO/PWM
    _pwm = initialize_gpio()
    if _pwm is None:
        cleanup()
        sys.exit(1)

    print("TSL2561 light-to-PWM controller started. Press Ctrl+C to exit.")

    try:
        while _running:
            lux = read_light_level(light_sensor)
            brightness = calculate_brightness(lux)

            if lux is not None:
                print(f"Light Level: {lux:.2f} lux, Brightness: {brightness:.2f}%")
            else:
                print(f"Light Level: ERROR, Brightness: {brightness:.2f}%")

            try:
                _pwm.ChangeDutyCycle(brightness)
            except Exception as e:
                print(f"Error updating PWM duty cycle: {e}", file=sys.stderr)

            # Sleep in small increments to allow prompt signal handling
            elapsed = 0.0
            while _running and elapsed < UPDATE_INTERVAL:
                time.sleep(0.1)
                elapsed += 0.1

    except Exception as e:
        print(f"Unexpected error in main loop: {e}", file=sys.stderr)
    finally:
        cleanup()
        print("Cleanup complete. Exiting.")


if __name__ == "__main__":
    main()

