import csv
import signal
import sys
from datetime import datetime

from gpiozero import Button, LED

TOUCH_SENSOR_PIN = 17
LED_OUTPUT_PIN = 27
LOG_FILE = 'touch_events.csv'
DEBOUNCE_TIME = 0.3

running = True

def signal_handler(signum, frame):
    global running
    running = False

def log_touch_event(log_file):
    timestamp = datetime.now().isoformat(timespec='seconds')
    try:
        with open(log_file, 'a', newline='') as csvfile:
            csv.writer(csvfile).writerow([timestamp, 'Touch Detected'])
    except IOError as e:
        print(f"Error writing to log file: {e}", file=sys.stderr)

def main():
    global running
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    try:
        touch_sensor = Button(TOUCH_SENSOR_PIN, pull_up=True, bounce_time=DEBOUNCE_TIME)
        led = LED(LED_OUTPUT_PIN)
    except Exception as e:
        print(f"Failed to initialize GPIO devices: {e}", file=sys.stderr)
        sys.exit(1)

    try:
        with open(LOG_FILE, 'w', newline='') as csvfile:
            csv.writer(csvfile).writerow(['Timestamp', 'Event'])
    except IOError as e:
        print(f"Error creating log file: {e}", file=sys.stderr)
        sys.exit(1)

    try:
        while running:
            if touch_sensor.is_pressed:
                led.on()
                log_touch_event(LOG_FILE)
                while touch_sensor.is_pressed and running:
                    pass
                led.off()
    except Exception as e:
        print(f"Unexpected error: {e}", file=sys.stderr)
    finally:
        try:
            led.close()
            touch_sensor.close()
        except Exception:
            pass
        print("GPIO cleanup completed.")

if __name__ == '__main__':
    main()

