import sys
import signal

try:
    from gpiozero import PWMOutputDevice
    from gpiozero.exc import GPIOZeroError, GPIODeviceError
except ImportError:
    print("Error: gpiozero library is required. Install with: sudo apt install python3-gpiozero")
    sys.exit(1)

FAN_PIN = 12
PWM_FREQUENCY = 25000  # 25 kHz standard for 4-wire PWM fans

fan = None
running = True


def cleanup():
    """Stop PWM and release GPIO resources."""
    global fan
    if fan is not None:
        try:
            fan.close()
        except Exception:
            pass
        fan = None


def signal_handler(signum, frame):
    """Handle SIGTERM/SIGINT for clean shutdown."""
    global running
    running = False


def main():
    global fan

    # Register signal handlers for graceful termination
    signal.signal(signal.SIGTERM, signal_handler)
    signal.signal(signal.SIGINT, signal_handler)

    # Initialize PWM output device with error handling
    try:
        fan = PWMOutputDevice(FAN_PIN, frequency=PWM_FREQUENCY, initial_value=0.0)
    except (GPIOZeroError, GPIODeviceError) as e:
        print(f"Error initializing PWM on GPIO{FAN_PIN}: {e}")
        print("Falling back to software PWM (gpiozero may not support hardware PWM on this platform).")
        try:
            fan = PWMOutputDevice(FAN_PIN, frequency=PWM_FREQUENCY, initial_value=0.0, pin_factory=None)
        except Exception as e2:
            print(f"Error initializing software PWM: {e2}")
            sys.exit(1)
    except Exception as e:
        print(f"Unexpected error during GPIO initialization: {e}")
        sys.exit(1)

    print(f"PWM fan control started on GPIO{FAN_PIN} at {PWM_FREQUENCY} Hz. Press Ctrl+C to exit.")

    try:
        while running:
            try:
                user_input = input("Enter fan speed (0-100) or 'q' to quit: ").strip()
            except EOFError:
                print("\nEOF received, exiting.")
                break

            if user_input.lower() == 'q':
                break

            try:
                fan_speed = float(user_input)
            except ValueError:
                print("Invalid input. Please enter a number between 0 and 100 or 'q' to quit.")
                continue

            if not (0 <= fan_speed <= 100):
                print("Fan speed must be between 0 and 100.")
                continue

            # gpiozero expects a value between 0.0 and 1.0
            fan.value = fan_speed / 100.0
            print(f"Fan speed set to {fan_speed:.1f}%")

    except Exception as e:
        print(f"Runtime error: {e}")
    finally:
        cleanup()
        print("GPIO cleanup completed. Exiting.")


if __name__ == "__main__":
    main()

