#!/usr/bin/env python3
"""
Rainbow HAT 3-bit binary counter.

Touchpad A (GPIO5)  -> bit 2 (value 4)
Touchpad B (GPIO6)  -> bit 1 (value 2)
Touchpad C (GPIO12) -> bit 0 (value 1)

Discrete LEDs:
  Green (GPIO7)  -> bit 2
  Blue  (GPIO8)  -> bit 1
  Red   (GPIO9)  -> bit 0

HT16K33 14-segment display at I2C 0x70.
APA102 LED strip (7 pixels): data on GPIO10, clock on GPIO11.
Piezo buzzer on GPIO13.
"""

import signal
import sys
import time

import board
import busio
from gpiozero import Button, LED, Buzzer
from adafruit_ht16k33.segments import Seg7x4
from adafruit_aplx.apa102 import APA102

# ---------------------------------------------------------------------------
# Pin / peripheral definitions
# ---------------------------------------------------------------------------
TOUCH_PINS = {
    "A": board.D5,   # GPIO5  -> bit 2
    "B": board.D6,   # GPIO6  -> bit 1
    "C": board.D12,  # GPIO12 -> bit 0
}

DISCRETE_PINS = {
    "green": board.D7,   # GPIO7
    "blue":  board.D8,   # GPIO8
    "red":   board.D9,   # GPIO9
}

BUZZER_PIN = board.D13   # GPIO13

APA102_DATA_PIN = board.D10
APA102_CLOCK_PIN = board.D11

# ---------------------------------------------------------------------------
# Globals for cleanup
# ---------------------------------------------------------------------------
_touch_buttons = {}
_discrete_leds = {}
_buzzer = None
_display = None
_strip = None
_running = True


def _cleanup():
    """Turn off all outputs and release resources."""
    global _running
    _running = False

    for btn in _touch_buttons.values():
        try:
            btn.close()
        except Exception:
            pass

    for led in _discrete_leds.values():
        try:
            led.off()
            led.close()
        except Exception:
            pass

    if _buzzer is not None:
        try:
            _buzzer.off()
            _buzzer.close()
        except Exception:
            pass

    if _display is not None:
        try:
            _display.fill(0)
            _display.show()
        except Exception:
            pass

    if _strip is not None:
        try:
            _strip.fill((0, 0, 0))
            _strip.show()
        except Exception:
            pass


def _signal_handler(signum, frame):
    """Handle SIGINT / SIGTERM for graceful shutdown."""
    print(f"\nReceived signal {signum}, shutting down...", file=sys.stderr)
    _cleanup()
    sys.exit(0)


def init_touch_buttons():
    """Initialise gpiozero Button objects for the three touchpads."""
    for name, pin in TOUCH_PINS.items():
        try:
            _touch_buttons[name] = Button(pin, pull_up=True, bounce_time=0.05)
        except Exception as exc:
            print(f"Warning: could not initialise touchpad '{name}' on {pin}: {exc}",
                  file=sys.stderr)
            _touch_buttons[name] = None


def init_discrete_leds():
    """Initialise gpiozero LED objects for the three discrete LEDs."""
    for name, pin in DISCRETE_PINS.items():
        try:
            _discrete_leds[name] = LED(pin)
        except Exception as exc:
            print(f"Warning: could not initialise discrete LED '{name}' on {pin}: {exc}",
                  file=sys.stderr)
            _discrete_leds[name] = None


def init_buzzer():
    """Initialise the piezo buzzer."""
    global _buzzer
    try:
        _buzzer = Buzzer(BUZZER_PIN)
    except Exception as exc:
        print(f"Warning: could not initialise buzzer on {BUZZER_PIN}: {exc}",
              file=sys.stderr)
        _buzzer = None


def init_display():
    """Initialise the HT16K33 14-segment display at I2C 0x70."""
    global _display
    try:
        i2c = busio.I2C(board.SCL, board.SDA)
        _display = Seg7x4(i2c, address=0x70)
        _display.fill(0)
        _display.show()
    except Exception as exc:
        print(f"Warning: could not initialise display at 0x70: {exc}",
              file=sys.stderr)
        _display = None


def init_strip():
    """Initialise the APA102 LED strip (7 pixels)."""
    global _strip
    try:
        _strip = APA102(APA102_DATA_PIN, APA102_CLOCK_PIN, num_led=7)
        _strip.fill((0, 0, 0))
        _strip.show()
    except Exception as exc:
        print(f"Warning: could not initialise APA102 strip: {exc}",
              file=sys.stderr)
        _strip = None


# ---------------------------------------------------------------------------
# Touchpad callbacks
# ---------------------------------------------------------------------------
def on_touch(name):
    """Toggle the bit corresponding to *name* and update all outputs."""
    global _running
    if not _running:
        return

    bit_states = [False, False, False]
    for idx, btn_name in enumerate(("A", "B", "C")):
        btn = _touch_buttons.get(btn_name)
        if btn is not None:
            bit_states[idx] = btn.is_pressed

    bit_states[TOUCH_PINS[name].value] = not bit_states[TOUCH_PINS[name].value]

    # --- Discrete LEDs (green=bit2, blue=bit1, red=bit0) ---
    if _discrete_leds.get("green") is not None:
        _discrete_leds["green"].value = bit_states[2]
    if _discrete_leds.get("blue") is not None:
        _discrete_leds["blue"].value = bit_states[1]
    if _discrete_leds.get("red") is not None:
        _discrete_leds["red"].value = bit_states[0]

    # --- Decimal value (0-7) ---
    value = (bit_states[0] << 0) | (bit_states[1] << 1) | (bit_states[2] << 2)

    # --- 14-segment display ---
    if _display is not None:
        try:
            _display.print_hex(value)
            _display.show()
        except Exception as exc:
            print(f"Display update failed: {exc}", file=sys.stderr)

    # --- APA102 LED strip ---
    if _strip is not None:
        try:
            if value == 0:
                _strip.fill((64, 64, 64))
                _strip.pixel_buf[0] = (0, 0, 0)
            elif value == 7:
                _strip.fill((255, 255, 255))
            else:
                _strip.fill((0, 0, 0))
                _strip.pixel_buf[value] = (
                    255 if bit_states[0] else 0,
                    255 if bit_states[1] else 0,
                    255 if bit_states[2] else 0,
                )
            _strip.show()
        except Exception as exc:
            print(f"Strip update failed: {exc}", file=sys.stderr)

    # --- Piezo buzzer (MIDI note 60 + decimal value) ---
    if _buzzer is not None:
        try:
            _buzzer.play(60 + value)
            time.sleep(0.5)
            _buzzer.stop()
        except Exception as exc:
            print(f"Buzzer failed: {exc}", file=sys.stderr)


# ---------------------------------------------------------------------------
# Main
# ---------------------------------------------------------------------------
def main():
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    init_touch_buttons()
    init_discrete_leds()
    init_buzzer()
    init_display()
    init_strip()

    # Register touch callbacks
    for name in TOUCH_PINS:
        btn = _touch_buttons.get(name)
        if btn is not None:
            btn.when_pressed = lambda n=name: on_touch(n)

    print("Rainbow HAT binary counter ready. Touch the touchpads to toggle bits.",
          file=sys.stderr)

    try:
        signal.pause()
    except KeyboardInterrupt:
        pass
    finally:
        _cleanup()


if __name__ == "__main__":
    main()

