            _buzzer.stop()
        except Exception as exc:
            print(f"Buzzer failed: {exc}", file=sys.stderr)


# ---------------------------------------------------------------------------
# Main
# ---------------------------------------------------------------------------
def main():
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    init_touch_buttons()
    init_discrete_leds()
    init_buzzer()
    init_display()
    init_strip()

    # Register touch callbacks
    for name in TOUCH_PINS:
        btn = _touch_buttons.get(name)
        if btn is not None:
            btn.when_pressed = lambda n=name: on_touch(n)

    print("Rainbow HAT binary counter ready. Touch the touchpads to toggle bits.",
          file=sys.stderr)

    try:
        signal.pause()
    except KeyboardInterrupt:
        pass
    finally:
        _cleanup()


if __name__ == "__main__":
    main()

