import time
import signal
import sys
import board
import busio
import adafruit_tcs34725
from PIL import Image

# Global flag for graceful shutdown
_running = True

def _signal_handler(signum, frame):
    global _running
    _running = False

def initialize_i2c():
    """Initialize the I2C bus on board.SCL (BCM GPIO3) and board.SDA (BCM GPIO2)."""
    try:
        i2c_bus = busio.I2C(board.SCL, board.SDA)
        return i2c_bus
    except Exception as e:
        print(f"Error initializing I2C bus: {e}", file=sys.stderr)
        return None

def initialize_color_sensor(i2c_bus):
    """Initialize the TCS34725 color sensor at address 0x29."""
    try:
        color_sensor = adafruit_tcs34725.TCS34725(i2c_bus)
        # Set integration time to 50 ms and gain to 4x
        color_sensor.integration_time = adafruit_tcs34725.INTEGRATION_TIME_50MS
        color_sensor.gain = adafruit_tcs34725.GAIN_4X
        return color_sensor
    except ValueError as e:
        print(f"TCS34725 not found at default address 0x29: {e}", file=sys.stderr)
        return None
    except Exception as e:
        print(f"Error initializing TCS34725 sensor: {e}", file=sys.stderr)
        return None

def get_sensor_color_data(color_sensor):
    """Read red, green, blue, and clear channel values from the sensor."""
    try:
        red, green, blue, clear = color_sensor.color_rgb_bytes
        return red, green, blue, clear
    except Exception as e:
        print(f"Error reading sensor data: {e}", file=sys.stderr)
        return 0, 0, 0, 0

def find_dominant_image_color(image_path):
    """Find the dominant color in a local image file."""
    try:
        with Image.open(image_path) as image:
            # Resize to 100x100 for faster processing
            image = image.resize((100, 100))
            # Get the color histogram and find the most frequent color
            color_histogram = image.getcolors(10000)
            if color_histogram:
                dominant_color = max(color_histogram, key=lambda item: item[0])[1]
                return dominant_color
            else:
                return (0, 0, 0)
    except FileNotFoundError:
        print(f"Image file not found: {image_path}", file=sys.stderr)
        return (0, 0, 0)
    except Exception as e:
        print(f"Error processing image: {e}", file=sys.stderr)
        return (0, 0, 0)

def main():
    """Main function to read sensor data and image color."""
    global _running

    # Register signal handlers for graceful shutdown
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    i2c_bus = initialize_i2c()
    if i2c_bus is None:
        sys.exit(1)

    color_sensor = initialize_color_sensor(i2c_bus)
    if color_sensor is None:
        i2c_bus.deinit()
        sys.exit(1)

    image_path = "image.jpg"

    try:
        while _running:
            red, green, blue, clear = get_sensor_color_data(color_sensor)
            dominant_color = find_dominant_image_color(image_path)

            print(f"Sensor Color: R={red}, G={green}, B={blue}, Clear={clear}")
            print(f"Dominant Image Color: {dominant_color}")
            print("-" * 50)

            # Wait for 1 second, checking for shutdown every 0.1s
            for _ in range(10):
                if not _running:
                    break
                time.sleep(0.1)

    except Exception as e:
        print(f"Unexpected error in main loop: {e}", file=sys.stderr)
    finally:
        # Clean up resources
        try:
            i2c_bus.deinit()
            print("I2C bus deinitialized.")
        except Exception as e:
            print(f"Error deinitializing I2C bus: {e}", file=sys.stderr)
        print("Program terminated.")

if __name__ == "__main__":
    main()

