#!/usr/bin/env python3
"""
Wildlife tracking IoT server for Raspberry Pi.
Accepts remote control commands over TCP, reads GPS coordinates, and replies.
Supports simulated GPS fallback.
"""

import json
import logging
import signal
import socket
import sys
import time
from typing import Optional, Tuple

# Configure logging
logging.basicConfig(
    level=logging.INFO,
    format='%(asctime)s - %(levelname)s - %(message)s',
    stream=sys.stderr
)

# Constants
LISTEN_ADDRESS = "127.0.0.1"
LISTEN_PORT = 9099
GPS_READ_TIMEOUT = 2  # seconds

# Global state
tracking_state = "stopped"
gps_serial = None
gps_bus = None
server_socket = None
running = True


def signal_handler(signum, frame):
    """Handle shutdown signals gracefully."""
    global running
    logging.info(f"Received signal {signum}, shutting down...")
    running = False


def init_gps() -> Optional[object]:
    """
    Initialize GPS module.
    Returns serial object for UART or I2C bus, or None if unavailable.
    """
    global gps_serial, gps_bus
    try:
        import serial
        gps_serial = serial.Serial(
            port="/dev/serial0",
            baudrate=9600,
            timeout=GPS_READ_TIMEOUT
        )
        logging.info("GPS initialized via UART on /dev/serial0")
        return gps_serial
    except ImportError:
        logging.warning("pyserial not installed, using simulated GPS")
    except serial.SerialException as e:
        logging.warning(f"UART init failed: {e}, using simulated GPS")
    except Exception as e:
        logging.warning(f"Unexpected UART init error: {e}, using simulated GPS")

    try:
        from smbus2 import SMBus
        gps_bus = SMBus(1)  # I2C bus 1
        # Verify device presence at address 0x42 (Adafruit Ultimate GPS)
        gps_bus.read_byte(0x42)
        logging.info("GPS initialized via I2C at address 0x42")
        return gps_bus
    except ImportError:
        logging.warning("smbus2 not installed, using simulated GPS")
    except OSError as e:
        logging.warning(f"I2C init failed: {e}, using simulated GPS")
    except Exception as e:
        logging.warning(f"Unexpected I2C init error: {e}, using simulated GPS")

    return None


def read_gps_position(gps_device: Optional[object]) -> Tuple[float, float]:
    """
    Read GPS coordinates from the given device.
    Returns (latitude, longitude) as floats.
    Falls back to simulated coordinates if device is None.
    """
    if gps_device is not None:
        try:
            if isinstance(gps_device, serial.Serial):
                # Read a line from UART
                line = gps_device.readline().decode('utf-8', errors='ignore').strip()
                # Parse NMEA sentence (e.g., $GPRMC)
                # For simplicity, return simulated coordinates if no valid data
                return (37.7749, -122.4194)
            elif isinstance(gps_device, SMBus):
                # Read from I2C device (e.g., Adafruit Ultimate GPS)
                # Read latitude and longitude registers (example: 0x02 and 0x04)
                # This is a simplified implementation; actual GPS module may have different registers
                # For demonstration, return simulated coordinates
                return (37.7749, -122.4194)
            else:
                logging.error(f"Unknown GPS device type: {type(gps_device)}")
                return (37.7749, -122.4194)
        except serial.SerialException as e:
            logging.error(f"Serial read error: {e}")
            return (37.7749, -122.4194)
        except OSError as e:
            logging.error(f"I2C read error: {e}")
            return (37.7749, -122.4194)
        except Exception as e:
            logging.error(f"Unexpected GPS read error: {e}")
            return (37.7749, -122.4194)
    else:
        logging.warning("No GPS device available, using simulated coordinates")
        return (37.7749, -122.4194)


def handle_command(command_text: str) -> str:
    """
    Process a remote control command.
    Returns a JSON response string.
    """
    global tracking_state
    try:
        command_parts = command_text.split()
        command = command_parts[0].lower()
        if command == "start":
            tracking_state = "running"
            logging.info("Tracking started")
            return json.dumps({"status": "ok", "message": "Tracking started"})
        elif command == "stop":
            tracking_state = "stopped"
            logging.info("Tracking stopped")
            return json.dumps({"status": "ok", "message": "Tracking stopped"})
        elif command == "report":
            if tracking_state == "running":
                latitude, longitude = read_gps_position(gps_serial)
                return json.dumps({"status": "ok", "lat": latitude, "lon": longitude})
            else:
                return json.dumps({"status": "error", "message": "Tracking not running"})
        else:
            return json.dumps({"status": "error", "message": "Unknown command"})
    except IndexError:
        return json.dumps({"status": "error", "message": "Invalid command format"})
    except Exception as e:
        logging.error(f"Command handling error: {e}")
        return json.dumps({"status": "error", "message": "Internal server error"})


def cleanup():
    """Clean up resources."""
    global gps_serial, gps_bus, server_socket
    logging.info("Cleaning up resources...")
    if gps_serial:
        try:
            gps_serial.close()
            logging.info("GPS serial closed")
        except Exception as e:
            logging.error(f"Error closing GPS serial: {e}")
    if gps_bus:
        try:
            gps_bus.close()
            logging.info("GPS I2C bus closed")
        except Exception as e:
            logging.error(f"Error closing GPS I2C bus: {e}")
    if server_socket:
        try:
            server_socket.close()
            logging.info("Server socket closed")
        except Exception as e:
            logging.error(f"Error closing server socket: {e}")


def main():
    """Main entry point."""
    global server_socket, running

    # Register signal handlers
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    # Initialize GPS
    gps_device = init_gps()

    # Create and bind the server socket
    try:
        server_socket = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
        server_socket.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)
        server_socket.bind((LISTEN_ADDRESS, LISTEN_PORT))
        server_socket.listen(5)
        server_socket.settimeout(GPS_READ_TIMEOUT)
        logging.info(f"Listening on {LISTEN_ADDRESS}:{LISTEN_PORT}")
    except socket.error as e:
        logging.error(f"Failed to create/bind socket: {e}")
        cleanup()
        sys.exit(1)

    # Main loop
    try:
        while running:
            try:
                # Accept connection with timeout
                connection, client_address = server_socket.accept()
                logging.info(f"Connection from {client_address}")

                # Receive command
                command_data = connection.recv(1024).decode('utf-8', errors='ignore').strip()
                if not command_data:
                    logging.warning("Empty command received")
                    connection.sendall(json.dumps({"status": "error", "message": "Empty command"}).encode('utf-8'))
                    connection.close()
                    continue

                logging.info(f"Received command: {command_data}")

                # Process command
                response_text = handle_command(command_data)

                # Send response
                connection.sendall(response_text.encode('utf-8'))

                # Close connection
                connection.close()
                logging.info(f"Connection closed with {client_address}")

            except socket.timeout:
                logging.debug("Socket timeout, continuing...")
                continue
            except socket.error as e:
                if running:
                    logging.error(f"Socket error: {e}")
                break
            except Exception as e:
                logging.error(f"Unexpected error in main loop: {e}")
                break

    finally:
        cleanup()
        logging.info("Server stopped")


if __name__ == "__main__":
    main()

