#!/usr/bin/env python3
"""
Automated Chicken Coop Door Controller
Controls a relay on GPIO 17 (BCM) to open/close a door based on sunrise/sunset times.
"""

import RPi.GPIO as GPIO
import time
import datetime
import sys

# Configuration
RELAY_PIN = 17
SUNRISE_TIME = datetime.time(7, 0, 0)
SUNSET_TIME = datetime.time(19, 0, 0)
CHECK_INTERVAL = 60  # seconds

def setup_gpio():
    """Initialize GPIO with error handling."""
    try:
        GPIO.setmode(GPIO.BCM)
        GPIO.setup(RELAY_PIN, GPIO.OUT, initial=GPIO.HIGH)  # Start with door closed
    except RuntimeError as e:
        print(f"GPIO setup failed: {e}")
        sys.exit(1)

def cleanup_gpio():
    """Safely clean up GPIO resources."""
    GPIO.cleanup()

def main():
    setup_gpio()
    print("Chicken coop door controller started. Press Ctrl+C to exit.")

    try:
        while True:
            current_time = datetime.datetime.now().time()
            # Check if current time is between sunrise and sunset (inclusive)
            if SUNRISE_TIME <= current_time <= SUNSET_TIME:
                if GPIO.input(RELAY_PIN) == GPIO.HIGH:
                    GPIO.output(RELAY_PIN, GPIO.LOW)
                    print("Door opened (relay energized)")
            else:
                if GPIO.input(RELAY_PIN) == GPIO.LOW:
                    GPIO.output(RELAY_PIN, GPIO.HIGH)
                    print("Door closed (relay de-energized)")

            time.sleep(CHECK_INTERVAL)

    except KeyboardInterrupt:
        print("\nExiting program...")
    except Exception as e:
        print(f"Unexpected error: {e}")
    finally:
        cleanup_gpio()
        print("GPIO cleaned up.")

if __name__ == "__main__":
    main()

