import random
import time
import signal
import sys
from gpiozero import LED
from gpiozero.exc import GPIOZeroError, GPIODeviceError

LED_PIN = 17
NUM_CYCLES = 5
DELAY_SECONDS = 2
LIGHT_THRESHOLD = 50

def simulate_light_level():
    """Simulate a light sensor reading as a percentage (0-100 inclusive)."""
    return random.randint(0, 100)

def main():
    # Initialize the LED on GPIO 17 using gpiozero with BCM numbering.
    # gpiozero automatically configures the pin as an output and sets it LOW.
    try:
        led = LED(LED_PIN)
    except (GPIOZeroError, GPIODeviceError) as e:
        print(f"Failed to initialize LED on GPIO {LED_PIN}: {e}", file=sys.stderr)
        sys.exit(1)

    def cleanup():
        """Turn off the LED and release GPIO resources."""
        try:
            led.off()
            led.close()
        except Exception:
            pass

    # Ensure cleanup on SIGTERM (e.g., systemd stop) as well as KeyboardInterrupt.
    def signal_handler(signum, frame):
        print(f"\nReceived signal {signum}, exiting...")
        cleanup()
        sys.exit(0)

    signal.signal(signal.SIGTERM, signal_handler)

    try:
        for cycle in range(1, NUM_CYCLES + 1):
            light_level = simulate_light_level()
            print(f"Cycle {cycle}/{NUM_CYCLES}: Light Level = {light_level}%")

            if light_level < LIGHT_THRESHOLD:
                led.on()
                print("  -> LED ON: Low light detected")
            else:
                led.off()
                print("  -> LED OFF: Sufficient light")

            if cycle < NUM_CYCLES:
                time.sleep(DELAY_SECONDS)

        print("Simulation complete.")

    except KeyboardInterrupt:
        print("\nProgram interrupted by user.")
    except Exception as e:
        print(f"Unexpected error: {e}", file=sys.stderr)
    finally:
        cleanup()

if __name__ == "__main__":
    main()

