import serial
import time
import logging
import signal
import sys
import RPi.GPIO as GPIO

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

class GSMModule:
    def __init__(self, port='/dev/serial0', baudrate=115200, timeout=2, power_pin=4):
        self.port = port
        self.baudrate = baudrate
        self.timeout = timeout
        self.power_pin = power_pin
        self.serial_port = None
        self._running = True

        signal.signal(signal.SIGINT, self._signal_handler)
        signal.signal(signal.SIGTERM, self._signal_handler)

        try:
            GPIO.setmode(GPIO.BCM)
            GPIO.setup(self.power_pin, GPIO.OUT, initial=GPIO.LOW)
            logging.info(f"Power pin {self.power_pin} configured as output.")
        except Exception as e:
            logging.error(f"Failed to initialize GPIO: {e}")
            raise

        try:
            self.serial_port = serial.Serial(
                port=self.port,
                baudrate=self.baudrate,
                timeout=self.timeout
            )
            logging.info(f"Serial port {self.port} opened successfully.")
        except serial.SerialException as e:
            logging.error(f"Failed to open serial port {self.port}: {e}")
            self.cleanup()
            raise

        try:
            self._power_on_module()
        except Exception as e:
            logging.error(f"Module power-on failed: {e}")
            self.cleanup()
            raise

        if not self._verify_module_response():
            logging.error("Module did not respond to AT commands.")
            self.cleanup()
            raise

    def _signal_handler(self, signum, frame):
        logging.info(f"Signal {signum} received, shutting down.")
        self._running = False
        self.cleanup()
        sys.exit(0)

    def _power_on_module(self):
        logging.info("Powering on GSM module...")
        GPIO.output(self.power_pin, GPIO.HIGH)
        time.sleep(2)
        GPIO.output(self.power_pin, GPIO.LOW)
        time.sleep(3)
        logging.info("GSM module powered on.")

    def _verify_module_response(self):
        logging.info("Verifying module response...")
        for _ in range(3):
            if self._send_at_command('AT') == 'OK':
                logging.info("Module responded with OK.")
                return True
            time.sleep(1)
        return False

    def _send_at_command(self, command, expected_response='OK', attempts=5):
        if not self.serial_port or not self.serial_port.is_open:
            logging.error("Serial port is not open.")
            return None

        try:
            self.serial_port.reset_input_buffer()
            self.serial_port.write((command + '\r\n').encode('utf-8'))
            logging.debug(f"Sent: {command}")

            for _ in range(attempts):
                if self.serial_port.in_waiting > 0:
                    response = self.read_response()
                    if response:
                        logging.debug(f"Received: {response}")
                        if expected_response in response:
                            return response
                        else:
                            logging.warning(f"Unexpected response: {response}")
                            return None
                time.sleep(0.1)

            logging.warning(f"No response to {command} after {attempts} attempts.")
            return None
        except serial.SerialException as e:
            logging.error(f"Serial communication error: {e}")
            return None

    def read_response(self, attempts=5):
        if not self.serial_port or not self.serial_port.is_open:
            logging.error("Serial port is not open.")
            return None

        response = b''
        try:
            for _ in range(attempts):
                if self.serial_port.in_waiting > 0:
                    chunk = self.serial_port.read(self.serial_port.in_waiting)
                    if chunk:
                        response += chunk
                else:
                    break
            return response.decode('utf-8', errors='ignore').strip()
        except serial.SerialException as e:
            logging.error(f"Serial read error: {e}")
            return None

    def set_gps_reporting(self, interval_seconds=10):
        command = f'AT+GPSRD={interval_seconds}'
        response = self._send_at_command(command, expected_response='OK')
        if response:
            logging.info(f"GPS reporting interval set to {interval_seconds} seconds.")
            return True
        else:
            logging.error(f"Failed to set GPS reporting interval to {interval_seconds} seconds.")
            return False

    def set_message_storage(self, storage='SM'):
        command = f'AT+CPMS="{storage}","{storage}","{storage}"'
        response = self._send_at_command(command, expected_response='OK')
        if response:
            logging.info(f"Message storage set to {storage}.")
            return True
        else:
            logging.error(f"Failed to set message storage to {storage}.")
            return False

    def send_tcp_data(self, data, ip='192.168.100.12', port=50):
        if not self.serial_port or not self.serial_port.is_open:
            logging.error("Serial port is not open.")
            return False

        try:
            logging.info(f"Connecting to TCP server at {ip}:{port}...")
            response = self._send_at_command(f'AT+CIPSTART="TCP","{ip}",{port}', expected_response='OK', attempts=10)
            if not response:
                logging.error("Failed to establish TCP connection.")
                return False

            logging.info("Sending data...")
            send_response = self._send_at_command(f'AT+CIPSEND={len(data)}', expected_response='>', attempts=5)
