from flask import Flask, request, jsonify
from gpiozero import OutputDevice
from gpiozero.exc import GPIOZeroError, GPIODeviceError
import signal
import sys

app = Flask(__name__)

RELAY_PIN = 23
relay = None

def cleanup(signum=None, frame=None):
    global relay
    if relay is not None:
        try:
            relay.close()
        except Exception:
            pass
        relay = None
    if signum is not None:
        sys.exit(0)

signal.signal(signal.SIGINT, cleanup)
signal.signal(signal.SIGTERM, cleanup)

@app.route('/relay', methods=['POST'])
def handle_relay():
    global relay
    if relay is None:
        try:
            relay = OutputDevice(RELAY_PIN)
        except (GPIOZeroError, GPIODeviceError) as e:
            return jsonify({'error': f'Failed to initialize GPIO pin {RELAY_PIN}: {e}'}), 500

    try:
        data = request.get_json(silent=True)
        if not isinstance(data, dict):
            return jsonify({'error': 'Invalid request: JSON body is required'}), 400

        state = data.get('state')
        if state is None:
            return jsonify({'error': 'Invalid request: "state" key is required'}), 400

        if state == 'on':
            relay.on()
        elif state == 'off':
            relay.off()
        else:
            return jsonify({'error': 'Invalid request: "state" must be "on" or "off"'}), 400

        return jsonify({'status': 'Relay state changed'}), 200

    except (GPIOZeroError, GPIODeviceError) as e:
        return jsonify({'error': f'GPIO operation failed: {e}'}), 500
    except Exception as e:
        return jsonify({'error': f'Internal server error: {e}'}), 500

if __name__ == '__main__':
    try:
        app.run(host='0.0.0.0', port=5000, debug=False)
    finally:
        cleanup()

