#!/usr/bin/env python3
"""
Automated Chicken Coop Door Controller
Hardware: Raspberry Pi, Relay Module (active-high) on GPIO17
"""

import RPi.GPIO as GPIO
import time
import datetime
import logging
import sys

# Configure logging
logging.basicConfig(
    level=logging.INFO,
    format='%(asctime)s - %(levelname)s - %(message)s'
)

# GPIO pin for relay (BCM numbering)
RELAY_PIN = 17

# Sunrise and sunset times (24-hour format)
SUNRISE_TIME = datetime.time(7, 0)
SUNSET_TIME = datetime.time(19, 0)

def setup_gpio():
    """Initialize GPIO with error handling."""
    try:
        GPIO.setmode(GPIO.BCM)
        GPIO.setup(RELAY_PIN, GPIO.OUT, initial=GPIO.LOW)
        logging.info("GPIO setup complete: pin %d set as output, initial LOW", RELAY_PIN)
    except Exception as e:
        logging.error("GPIO setup failed: %s", e)
        sys.exit(1)

def get_current_time():
    """Return current time as datetime.time."""
    return datetime.datetime.now().time()

def is_daytime():
    """Return True if current time is between sunrise and sunset."""
    current = get_current_time()
    return SUNRISE_TIME <= current < SUNSET_TIME

def close_door():
    """Energize relay to close door."""
    try:
        GPIO.output(RELAY_PIN, GPIO.HIGH)
        logging.info("Door closed (relay HIGH)")
    except Exception as e:
        logging.error("Failed to close door: %s", e)

def open_door():
    """De-energize relay to open door."""
    try:
        GPIO.output(RELAY_PIN, GPIO.LOW)
        logging.info("Door opened (relay LOW)")
    except Exception as e:
        logging.error("Failed to open door: %s", e)

def main():
    """Main control loop."""
    setup_gpio()
    logging.info("Chicken coop door controller started")

    try:
        while True:
            if is_daytime():
                close_door()
            else:
                open_door()
            time.sleep(60)  # Check every 60 seconds
    except KeyboardInterrupt:
        logging.info("Program interrupted by user")
    except Exception as e:
        logging.error("Unexpected error: %s", e)
    finally:
        GPIO.cleanup()
        logging.info("GPIO cleanup complete")

if __name__ == "__main__":
    main()

