class DS1338:
    """Driver for the Maxim DS1338 I2C Real-Time Clock (RTC)."""

    # Register addresses
    REG_SECONDS = 0x00
    REG_MINUTES = 0x01
    REG_HOURS = 0x02
    REG_DATE = 0x04
    REG_MONTH = 0x05
    REG_YEAR = 0x06

    # Bit masks
    HOUR_24_BIT = 0x40  # Bit 6: 12/24-hour mode (0 = 12-hour, 1 = 24-hour)

    def __init__(self, i2c_bus=1, address=0x68):
        """Initialize the DS1338 driver.

        Args:
            i2c_bus: I2C bus number (default 1 on Raspberry Pi).
            address: I2C address of the DS1338 (default 0x68).

        Raises:
            OSError: If the I2C bus cannot be opened or the device is not found.
        """
        self.address = address
        self.bus = None
        self._running = True

        try:
            self.bus = SMBus(i2c_bus)
        except OSError as e:
            raise OSError(f"Failed to open I2C bus {i2c_bus}: {e}") from e

        # Verify device presence by reading the seconds register
        try:
            self.bus.read_byte_data(self.address, self.REG_SECONDS)
        except OSError as e:
            self.close()
            raise OSError(
                f"No DS1338 found at address 0x{address:02X} on bus {i2c_bus}: {e}"
            ) from e

        # Register signal handlers for clean shutdown
