import serial
import time
import signal
import sys

# Global flag for graceful shutdown
_running = True

def signal_handler(sig, frame):
    """Handle SIGINT (Ctrl+C) for graceful shutdown."""
    global _running
    _running = False

def nmea_to_decimal(raw_coordinate, direction):
    """Converts NMEA coordinate (ddmm.mmmm) to decimal degrees."""
    if not raw_coordinate or not direction:
        return None
    try:
        dot_index = raw_coordinate.index('.')
        degrees = int(raw_coordinate[:dot_index - 2])
        minutes = float(raw_coordinate[dot_index - 2:])
        decimal = degrees + (minutes / 60.0)
        if direction in ('S', 'W'):
            decimal = -decimal
        return decimal
    except (ValueError, IndexError):
        return None

def parse_gprmc(nmea_sentence):
    """Parses a $GPRMC sentence and returns (latitude, longitude) or (None, None)."""
    if not nmea_sentence.startswith('$GPRMC'):
        return None, None
    try:
        parts = nmea_sentence.split(',')
        if len(parts) < 7:
            return None, None
        status = parts[2]
        if status != 'A':
            return None, None
        lat = nmea_to_decimal(parts[3], parts[4])
        lon = nmea_to_decimal(parts[5], parts[6])
        return lat, lon
    except (ValueError, IndexError):
        return None, None

def main():
    global _running
    signal.signal(signal.SIGINT, signal_handler)

    serial_port = '/dev/serial0'
    baud_rate = 9600
    timeout = 1

    ser = None
    try:
        ser = serial.Serial(serial_port, baud_rate, timeout=timeout)
        print(f"Opened {serial_port} at {baud_rate} baud. Press Ctrl+C to stop.")

        while _running:
            try:
                raw_line = ser.readline()
                if not raw_line:
                    continue
                line = raw_line.decode('ascii', errors='replace').strip()
                if not line:
                    continue
                lat, lon = parse_gprmc(line)
                if lat is not None and lon is not None:
                    print(f"Latitude: {lat:.6f}, Longitude: {lon:.6f}")
            except serial.SerialException as e:
                print(f"Serial read error: {e}")
                break
            except Exception as e:
                print(f"Unexpected error processing line: {e}")
                break
            time.sleep(1)

    except serial.SerialException as e:
        print(f"Failed to open serial port {serial_port}: {e}")
        sys.exit(1)
    except Exception as e:
        print(f"Unexpected error: {e}")
        sys.exit(1)
    finally:
        if ser is not None and ser.is_open:
            ser.close()
            print("Serial port closed.")

if __name__ == "__main__":
    main()

