BAUD_RATE = 9600
TIMEOUT = 1
LOG_FILE = 'gps_coordinates_log.txt'

running = True

def signal_handler(sig, frame):
    global running
    running = False

def parse_gpgga(data):
    if not data.startswith('$GPGGA'):
        return None, None, None
    fields = data.split(',')
    if len(fields) < 7:
        return None, None, None
    fix_quality = fields[6]
    if fix_quality != '1':
        return None, None, None
    latitude = fields[2]
    longitude = fields[4]
    altitude = fields[9]
    return latitude, longitude, altitude

def log_coordinates(latitude, longitude, altitude):
    timestamp = time.strftime('%Y-%m-%dT%H:%M:%S')
    log_entry = f'{timestamp} - Latitude: {latitude}, Longitude: {longitude}, Altitude: {altitude}\n'
    try:
        with open(LOG_FILE, 'a') as f:
            f.write(log_entry)
    except IOError as e:
        print(f'Error writing to log file: {e}', file=sys.stderr)

def main():
    global running
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    try:
        ser = serial.Serial(SERIAL_PORT, BAUD_RATE, timeout=TIMEOUT)
    except serial.SerialException as e:
        print(f'Error opening serial port: {e}', file=sys.stderr)
