stop_event = threading.Event()


def signal_handler(signum, frame):
    print(f"\nReceived signal {signum}, shutting down...")
    stop_event.set()


def read_flow_rate(serial_connection):
    try:
        raw_data = serial_connection.readline()
        if not raw_data:
            return None
        decoded_data = raw_data.decode('ascii', errors='replace').strip()
        if not decoded_data:
            return None
        return float(decoded_data)
    except ValueError:
