import serial
import pynmea2
import logging
import signal
import sys
from dataclasses import dataclass
from typing import Optional

logging.basicConfig(
    level=logging.INFO,
    format="%(asctime)s [%(levelname)s] %(message)s",
)
logger = logging.getLogger(__name__)


@dataclass
class GPS_readings:
    latitude: float
    longitude: float
    altitude: float
    satellites: int


class GPSReader:
    def __init__(self, port: str = "/dev/serial0", baudrate: int = 9600, timeout: float = 1.0):
        self.port = port
        self.baudrate = baudrate
        self.timeout = timeout
        self.serial_port: Optional[serial.Serial] = None
        self._running = True

    def connect(self) -> bool:
        try:
            self.serial_port = serial.Serial(
                port=self.port,
                baudrate=self.baudrate,
                bytesize=serial.EIGHTBITS,
                parity=serial.PARITY_NONE,
                stopbits=serial.STOPBITS_ONE,
                timeout=self.timeout,
            )
            logger.info("Connected to GPS on %s @ %d baud", self.port, self.baudrate)
            return True
        except serial.SerialException as e:
            logger.error("Failed to open serial port %s: %s", self.port, e)
            self.serial_port = None
            return False
        except Exception as e:
            logger.error("Unexpected error opening %s: %s", self.port, e)
            self.serial_port = None
            return False

    def disconnect(self) -> None:
        if self.serial_port is not None:
            try:
                if self.serial_port.is_open:
                    self.serial_port.close()
                    logger.info("Serial port closed.")
            except Exception as e:
                logger.error("Error closing serial port: %s", e)
            finally:
                self.serial_port = None

    def _signal_handler(self, signum, frame):
        logger.info("Signal %d received, shutting down...", signum)
        self._running = False

    def read_gps_data(self) -> Optional[GPS_readings]:
        if self.serial_port is None or not self.serial_port.is_open:
            logger.warning("Serial port not open; cannot read GPS data.")
            return None

        try:
            raw = self.serial_port.readline()
        except serial.SerialException as e:
            logger.error("Serial read error: %s", e)
            return None
        except Exception as e:
            logger.error("Unexpected read error: %s", e)
            return None

        if not raw:
            logger.warning("Read timeout: no data received within %.1f seconds.", self.timeout)
            return None

        try:
            nmea_data = raw.decode("latin-1").strip()
        except Exception as e:
            logger.error("Failed to decode serial data: %s", e)
            return None

        if not nmea_data:
            return None

        try:
            msg = pynmea2.parse(nmea_data)
        except pynmea2.ParseError as e:
            logger.warning("NMEA parse error: %s | raw: %r", e, nmea_data)
            return None
        except Exception as e:
            logger.error("Unexpected parse error: %s | raw: %r", e, nmea_data)
            return None

        if not isinstance(msg, pynmea2.GGA):
            logger.debug("Received non-GGA sentence: %s", type(msg).__name__)
            return None

        try:
            latitude = self._convert_to_decimal(msg.latitude, msg.latitude_direction)
            longitude = self._convert_to_decimal(msg.longitude, msg.longitude_direction)
            altitude = float(msg.altitude)
            satellites = int(msg.num_satellites)
        except (ValueError, TypeError) as e:
            logger.warning("Invalid coordinate/altitude data: %s | raw: %r", e, nmea_data)
            return None

        return GPS_readings(latitude, longitude, altitude, satellites)

    @staticmethod
    def _convert_to_decimal(coordinate: float, direction: str) -> float:
        if direction not in ("N", "S", "E", "W"):
            raise ValueError(f"Invalid direction '{direction}'; expected N/S/E/W")
        degrees = int(coordinate // 100)
        minutes = coordinate - (degrees * 100)
        decimal = degrees + (minutes / 60.0)
        if direction in ("S", "W"):
            decimal = -decimal
        return decimal


def main():
    gps = GPSReader(port="/dev/serial0", baudrate=9600, timeout=1.0)

    signal.signal(signal.SIGINT, gps._signal_handler)
    signal.signal(signal.SIGTERM, gps._signal_handler)

    if not gps.connect():
        sys.exit(1)

    try:
        while gps._running:
            readings = gps.read_gps_data()
            if readings is not None:
                logger.info(
                    "Lat: %.6f, Lon: %.6f, Alt: %.2f m, Sats: %d",
                    readings.latitude,
                    readings.longitude,
                    readings.altitude,
                    readings.satellites,
                )
    except Exception as e:
        logger.error("Fatal error in main loop: %s", e)
    finally:
        gps.disconnect()


if __name__ == "__main__":
    main()

