import serial
import logging
import signal
import sys

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

class SimpleGPS:
    def __init__(self, port='/dev/serial0', baudrate=9600, timeout=1):
        self.port = port
        self.baudrate = baudrate
        self.timeout = timeout
        self.serial_connection = None
        self._running = True

    def connect(self):
        try:
            self.serial_connection = serial.Serial(
                port=self.port,
                baudrate=self.baudrate,
                bytesize=serial.EIGHTBITS,
                parity=serial.PARITY_NONE,
                stopbits=serial.STOPBITS_ONE,
                timeout=self.timeout
            )
            logging.info(f"Connected to GPS on {self.port} at {self.baudrate} baud.")
            return True
        except serial.SerialException as e:
            logging.error(f"Serial connection error: {e}")
            self.serial_connection = None
            return False
        except OSError as e:
            logging.error(f"OS error opening serial port: {e}")
            self.serial_connection = None
            return False

    def read_data(self):
        if not self.serial_connection or not self.serial_connection.is_open:
            logging.error("Serial connection is not open.")
            return None
        try:
            if self.serial_connection.in_waiting > 0:
                raw_data = self.serial_connection.readline()
                if not raw_data:
                    return None
                data = raw_data.decode('utf-8', errors='ignore').strip()
                return data
            return None
        except serial.SerialException as e:
            logging.error(f"Serial read error: {e}")
            return None
        except OSError as e:
            logging.error(f"OS error during serial read: {e}")
            return None

    def parse_gga(self, data):
        if not data:
            return None
        if not data.startswith('$GPGGA') and not data.startswith('$GNGGA'):
            return None
        try:
            parts = data.split(',')
            if len(parts) < 15:
                logging.warning(f"Malformed GGA sentence (not enough fields): {data}")
                return None
            utc_time = parts[1]
            latitude = parts[2]
            latitude_dir = parts[3]
            longitude = parts[4]
            longitude_dir = parts[5]
            fix_quality = parts[6]
            num_satellites = parts[7]

            if not utc_time or not latitude or not latitude_dir or not longitude or not longitude_dir:
                logging.warning(f"GGA sentence missing required fields: {data}")
                return None

            lat_deg = float(latitude[:-2])
            lat_min = float(latitude[-2:])
            latitude_decimal = lat_deg + (lat_min / 60.0)
            if latitude_dir == 'S':
                latitude_decimal = -latitude_decimal

            lon_deg = float(longitude[:-2])
            lon_min = float(longitude[-2:])
            longitude_decimal = lon_deg + (lon_min / 60.0)
            if longitude_dir == 'W':
                longitude_decimal = -longitude_decimal

            return {
                'utc_time': utc_time,
                'latitude': latitude_decimal,
                'longitude': longitude_decimal,
                'fix_quality': fix_quality,
                'num_satellites': num_satellites
            }
        except (IndexError, ValueError) as e:
            logging.warning(f"Error parsing GGA sentence '{data}': {e}")
            return None

    def close(self):
        if self.serial_connection and self.serial_connection.is_open:
            try:
                self.serial_connection.close()
                logging.info("Serial connection closed.")
            except serial.SerialException as e:
                logging.error(f"Error closing serial connection: {e}")
            except OSError as e:
                logging.error(f"OS error closing serial connection: {e}")
            finally:
                self.serial_connection = None

    def stop(self):
        self._running = False

def main():
    gps = SimpleGPS()
    if not gps.connect():
        sys.exit(1)

    def signal_handler(sig, frame):
        logging.info("Interrupt received, shutting down...")
        gps.stop()

    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    try:
        while gps._running:
            data = gps.read_data()
            if data:
                parsed = gps.parse_gga(data)
                if parsed:
                    logging.info(f"GPS Data: {parsed}")
    except Exception as e:
        logging.error(f"Unexpected error in main loop: {e}")
    finally:
        gps.close()

if __name__ == '__main__':
    main()

