import signal
import sys
import threading
from typing import Optional, List, Dict, Any

from flask import Flask, Response, request, jsonify
import serial

app = Flask(__name__)

# ---------------------------------------------------------------------------
# SerialCommunicator
# ---------------------------------------------------------------------------
class SerialCommunicator:
    """Thread-safe serial communicator with robust error handling."""

    def __init__(self, port: str, baudrate: int = 9600):
        self.port = port
        self.baudrate = baudrate
        self.ser: Optional[serial.Serial] = None
        self._lock = threading.Lock()

    # -- context manager ----------------------------------------------------
    def __enter__(self) -> "SerialCommunicator":
        self.open()
        return self

    def __exit__(self, exc_type, exc_val, exc_tb) -> None:
        self.close()

    # -- lifecycle ----------------------------------------------------------
    def open(self) -> None:
        """Open the serial port, raising serial.SerialException on failure."""
        with self._lock:
            if self.ser is not None and self.ser.is_open:
                return
            try:
                self.ser = serial.Serial(
                    port=self.port,
                    baudrate=self.baudrate,
                    bytesize=serial.EIGHTBITS,
                    parity=serial.PARITY_NONE,
                    stopbits=serial.STOPBITS_ONE,
                    timeout=1.0,
                )
            except serial.SerialException as exc:
                self.ser = None
                raise

    def close(self) -> None:
        """Idempotently close the serial port."""
        with self._lock:
            if self.ser is not None:
                try:
                    if self.ser.is_open:
                        self.ser.close()
                except serial.SerialException:
                    pass
                finally:
                    self.ser = None

    # -- I/O ----------------------------------------------------------------
    def send(self, cmd: str) -> None:
        """Send a command string, verifying the byte count, and flushing."""
        if self.ser is None or not self.ser.is_open:
            raise serial.SerialException("Serial port is not open")
        payload = cmd.encode("ascii")
        try:
            written = self.ser.write(payload)
            if written != len(payload):
                raise serial.SerialException(
                    f"Short write: {written}/{len(payload)} bytes"
                )
            self.ser.flush()
        except serial.SerialException as exc:
            raise

    def receive_line(self) -> Optional[str]:
        """Read one line up to a newline, returning None on timeout/error."""
        if self.ser is None or not self.ser.is_open:
            return None
        try:
            raw = self.ser.readline()
        except serial.SerialException as exc:
            return None
        if not raw:
            return None
        return raw.decode("ascii", errors="replace").strip()


# ---------------------------------------------------------------------------
# DataManager
# ---------------------------------------------------------------------------
class DataManager:
    """Thread-safe in-memory data store with auto-incrementing IDs."""

    def __init__(self):
        self._data: List[Dict[str, Any]] = [
            {"id": 1, "name": "Item 1", "done": False},
            {"id": 2, "name": "Item 2", "done": True},
        ]
        self._lock = threading.Lock()
        self._next_id = 3

    def get_all(self) -> List[Dict[str, Any]]:
        with self._lock:
            return list(self._data)

    def get_by_id(self, item_id: int) -> Optional[Dict[str, Any]]:
        with self._lock:
            for item in self._data:
                if item["id"] == item_id:
                    return item
            return None

    def create(self, name: str, done: bool) -> Dict[str, Any]:
        if not name:
            raise ValueError("name must be a non-empty string")
        if not isinstance(done, bool):
            raise ValueError("done must be a boolean")
        with self._lock:
            item = {"id": self._next_id, "name": name, "done": done}
            self._data.append(item)
            self._next_id += 1
            return item


# ---------------------------------------------------------------------------
# Globals
# ---------------------------------------------------------------------------
data_manager = DataManager()
serial_comm: Optional[SerialCommunicator] = None


# ---------------------------------------------------------------------------
# Signal handling
# ---------------------------------------------------------------------------
def _signal_handler(signum, frame):
    print(f"\nReceived signal {signum}, shutting down...")
    if serial_comm is not None:
        serial_comm.close()
    sys.exit(0)


signal.signal(signal.SIGINT, _signal_handler)
signal.signal(signal.SIGTERM, _signal_handler)


