def get_version() -> Response:
    """Query the USB-serial instrument for its *IDN? response."""
    global serial_comm
    try:
        with SerialCommunicator("/dev/ttyUSB0", baudrate=9600) as comm:
            serial_comm = comm
            comm.send("*IDN?\n")
            response = comm.receive_line()
            if response is None:
                return Response("No response from device", status=504)
            return Response(response, mimetype="text/plain")
    except serial.SerialException as exc:
        print(f"Serial error: {exc}")
        return Response(f"Serial communication error: {exc}", status=500)
    except Exception as exc:
        print(f"Unexpected error: {exc}")
        return Response(f"Internal server error: {exc}", status=500)
    finally:
        if serial_comm is not None:
            serial_comm.close()
            serial_comm = None


@app.route("/data", methods=["GET"])
def get_all_data() -> Response:
    items = data_manager.get_all()
    return jsonify(items)


