from typing import Any, Dict, List, Optional

from flask import Flask, Response, request
import serial

app = Flask(__name__)

# ---------------------------------------------------------------------------
# In-memory data store
# ---------------------------------------------------------------------------
data_store: List[Dict[str, Any]] = [
    {"id": 1, "name": "Item 1", "done": False},
    {"id": 2, "name": "Item 2", "done": True},
]

# ---------------------------------------------------------------------------
# Serial port handle (global so signal handler can close it)
# ---------------------------------------------------------------------------
_serial_port: Optional[serial.Serial] = None


def _open_serial() -> serial.Serial:
    """Open and return the serial port, raising on failure."""
    global _serial_port
    if _serial_port is not None and _serial_port.is_open:
        return _serial_port
    _serial_port = serial.Serial(
        port="/dev/ttyUSB0",
        baudrate=9600,
        bytesize=serial.EIGHTBITS,
        parity=serial.PARITY_NONE,
        stopbits=serial.STOPBITS_ONE,
        timeout=1.0,
    )
    return _serial_port


def _close_serial() -> None:
    """Close the serial port if it is open."""
    global _serial_port
    if _serial_port is not None:
        try:
            if _serial_port.is_open:
                _serial_port.close()
        except Exception:
            pass
        _serial_port = None


def _signal_handler(signum: int, frame: Any) -> None:
    """Handle SIGINT / SIGTERM by shutting down cleanly."""
    _close_serial()
    sys.exit(0)


signal.signal(signal.SIGINT, _signal_handler)
signal.signal(signal.SIGTERM, _signal_handler)

# ---------------------------------------------------------------------------
# Routes
# ---------------------------------------------------------------------------
@app.route("/version", methods=["GET"])
def get_version() -> Response:
    """
    Open /dev/ttyUSB0 at 9600 baud, send '*IDN?\n', wait 0.1 s, read all
    bytes, return as text/html with newlines converted to <br>.
    On any error, return HTTP 503 with a clear error message and close
    the port.
    """
    ser: Optional[serial.Serial] = None
    try:
        ser = _open_serial()
        ser.reset_input_buffer()
        ser.reset_output_buffer()

        ser.write(b"*IDN?\n")
        ser.flush()
        time.sleep(0.1)

        raw = ser.read(4096)
        if not raw:
            return Response(
                "No response from instrument (timeout).",
                status=503,
                mimetype="text/plain",
            )

        return Response(
            raw.decode("ascii", errors="replace").replace("\n", "<br>"),
            mimetype="text/html",
        )

    except serial.SerialException as exc:
        return Response(
            f"Serial communication error: {exc}",
            status=503,
            mimetype="text/plain",
        )
    except OSError as exc:
        return Response(
            f"OS error opening serial port: {exc}",
            status=503,
            mimetype="text/plain",
        )
    finally:
        if ser is not None:
            try:
                if ser.is_open:
                    ser.close()
            except Exception:
                pass


