def get_data() -> Response:
    """Return the full data store as JSON."""
    return Response(
        json.dumps(data_store),
        mimetype="application/json",
    )


@app.route("/getset/<int:item_id>", methods=["GET"])
def get_set(item_id: int) -> Response:
    """Return a single item by id, or 404 if not found."""
    item = next((it for it in data_store if it["id"] == item_id), None)
    if item is None:
        return Response(
            f"Item with id {item_id} not found.",
            status=404,
            mimetype="text/plain",
        )
    return Response(
        json.dumps(item),
        mimetype="application/json",
    )


@app.route("/getpost/<int:item_id>/<name>", methods=["GET"])
def get_post(item_id: int, name: str) -> Response:
    """
    Append a new item to the store.  The item_id is used as the key; any
    existing item with that id is replaced.  The 'done' flag is set to
    False.
    """
    new_item = {"id": item_id, "name": name, "done": False}
    existing = next((it for it in data_store if it["id"] == item_id), None)
    if existing is not None:
        existing.update(new_item)
    else:
        data_store.append(new_item)
    return Response(
        json.dumps(data_store),
        mimetype="application/json",
    )


@app.route("/postjson", methods=["POST", "GET"])
def post_json() -> Response:
    """
    POST: create a new item with an auto-incremented id, name='', done=False.
    GET: return the current data store as JSON.
    """
    if request.method == "POST":
        try:
            if request.content_type == "application/json":
                body = request.get_json(silent=True)
            else:
                body = request.form.to_dict()

            if body is None:
                raise ValueError("Empty request body")

            name = body.get("name", "")
            done = bool(body.get("done", False))

            new_id = 1
            if data_store:
                new_id = max(it["id"] for it in data_store) + 1

            new_item = {"id": new_id, "name": name, "done": done}
            data_store.append(new_item)
            return Response(
                json.dumps(data_store),
                mimetype="application/json",
            )

        except (ValueError, TypeError) as exc:
            return Response(
                f"Invalid JSON or form data: {exc}",
                status=400,
                mimetype="text/plain",
            )

    # GET
    return Response(
        json.dumps(data_store),
        mimetype="application/json",
    )


if __name__ == "__main__":
    try:
        app.run(host="0.0.0.0", port=5000, debug=False)
    finally:
        _close_serial()

